export function solve(installed: string[], range: string): string | null {
  // Keep only string entries. lib.maxSatisfying tests each candidate with
  // Range.test, which rejects strings that are not valid versions, so invalid
  // entries are ignored. Prerelease handling follows npm semantics: a prerelease
  // matches only when the range names a prerelease on the same major.minor.patch.
  const candidates = installed.filter((v): v is string => typeof v === "string");
  return lib.maxSatisfying(candidates, range);
}

