const ALLOWED_PROTOCOLS = ['http', 'https'];

const LABEL_RE = /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i;
const TLD_RE = /^[a-z]{2,63}$/i;

function extractHost(url: string): string | null {
  const m = /^(https?):\/\/([^\/?#]*)/i.exec(url);
  if (!m) {
    return null;
  }
  let authority = m[2];
  const at = authority.lastIndexOf('@');
  if (at !== -1) {
    authority = authority.slice(at + 1);
  }
  const hp = /^([^:]+)(?::\d+)?$/.exec(authority);
  return hp ? hp[1] : null;
}

function isFqdn(host: string): boolean {
  if (host.length > 253) {
    return false;
  }
  const labels = host.split('.');
  if (labels.length < 2) {
    return false;
  }
  if (!labels.every((label) => LABEL_RE.test(label))) {
    return false;
  }
  return TLD_RE.test(labels[labels.length - 1]);
}

export function solve(urls: string[]): string[] {
  const options = {
    protocols: ALLOWED_PROTOCOLS,
    require_protocol: true,
    require_valid_protocol: true,
    require_tld: true,
    allow_underscores: false,
    allow_fragments: true,
    allow_query_components: true,
  };

  return urls.filter((url) => {
    if (typeof url !== 'string') {
      return false;
    }
    if (!lib.isURL(url, options)) {
      return false;
    }
    const host = extractHost(url);
    return host !== null && isFqdn(host);
  });
}

const GMAIL_DOMAINS: ReadonlySet<string> = new Set(['gmail.com', 'googlemail.com']);
const OUTLOOK_DOMAINS: ReadonlySet<string> = new Set(['outlook.com', 'hotmail.com', 'live.com']);

function canonicalize(raw: string): string {
  const email = raw.toLowerCase();
  const at = email.lastIndexOf('@');
  if (at < 0) {
    return email;
  }
  const domain = email.slice(at + 1);

  if (GMAIL_DOMAINS.has(domain)) {
    const normalized = lib.normalizeEmail(email, {
      gmail_remove_subaddress: true,
      gmail_remove_dots: true,
      gmail_lowercase: true,
      gmail_convert_googlemaildotcom: true,
      all_lowercase: true,
    });
    // The library returns false when the local part is empty.
    // The spec yields an empty local part in that case, so keep it as "@gmail.com".
    return typeof normalized === 'string' ? normalized : '@gmail.com';
  }

  if (OUTLOOK_DOMAINS.has(domain)) {
    const normalized = lib.normalizeEmail(email, {
      outlookdotcom_remove_subaddress: true,
      outlookdotcom_lowercase: true,
      all_lowercase: true,
    });
    return typeof normalized === 'string' ? normalized : `@${domain}`;
  }

  // Other domains: lowercase only (already applied above).
  return email;
}

export function solve(emails: string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];
  for (const raw of emails) {
    const canonical = canonicalize(raw);
    if (!seen.has(canonical)) {
      seen.add(canonical);
      result.push(canonical);
    }
  }
  return result;
}

export function solve(word: string, dictionary: string[]): string {
    if (dictionary.length === 0) {
        return "";
    }

    let best = dictionary[0];
    let bestDist = lib.distance(word, best);

    for (let i = 1; i < dictionary.length && bestDist > 0; i++) {
        const entry = dictionary[i];
        const d = lib.distance(word, entry);
        if (d < bestDist) {
            bestDist = d;
            best = entry;
        }
    }

    return best;
}

export function solve(nodes: string[], edges: [string, string][]): string[] {
  const known = new Set(nodes);
  for (const [from, to] of edges) {
    if (!known.has(from) || !known.has(to)) {
      throw new Error(`Unknown node in edge [${from}, ${to}]`);
    }
  }
  // lib.toposort throws on cyclic dependencies.
  return lib.toposort(nodes, edges);
}

