export function solve(name: string, namespace: string): string {
    // Parse the namespace UUID into 16 bytes.
    const nsHex = namespace.replace(/-/g, "");
    if (!/^[0-9a-fA-F]{32}$/.test(nsHex)) {
        throw new Error("Invalid namespace UUID");
    }
    const bytes: number[] = [];
    for (let i = 0; i < 16; i++) {
        bytes.push(parseInt(nsHex.slice(i * 2, i * 2 + 2), 16));
    }

    // Encode the name as UTF-8 by hand, replacing lone surrogates with U+FFFD.
    for (let i = 0; i < name.length; i++) {
        let cp = name.charCodeAt(i);
        if (cp >= 0xd800 && cp <= 0xdbff) {
            const lo = i + 1 < name.length ? name.charCodeAt(i + 1) : 0;
            if (lo >= 0xdc00 && lo <= 0xdfff) {
                cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
                i++;
            } else {
                cp = 0xfffd;
            }
        } else if (cp >= 0xdc00 && cp <= 0xdfff) {
            cp = 0xfffd;
        }

        if (cp < 0x80) {
            bytes.push(cp);
        } else if (cp < 0x800) {
            bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            bytes.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            bytes.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    // SHA-1 over namespace bytes followed by name bytes.
    const digest = lib.sha1(Uint8Array.from(bytes));

    // Set version (5) and RFC 4122 variant bits.
    const out = Array.from(digest.slice(0, 16));
    out[6] = (out[6] & 0x0f) | 0x50;
    out[8] = (out[8] & 0x3f) | 0x80;

    // Format as lowercase 8-4-4-4-12.
    const hex = out
        .map((b) => ("0" + b.toString(16)).slice(-2))
        .join("");
    return (
        hex.slice(0, 8) + "-" +
        hex.slice(8, 12) + "-" +
        hex.slice(12, 16) + "-" +
        hex.slice(16, 20) + "-" +
        hex.slice(20, 32)
    );
}

