export function solve(epochMs: number): string {
  if (!Number.isFinite(epochMs)) {
    throw new RangeError("epochMs must be a finite number");
  }
  // Floor to whole milliseconds, then drop the sub-second part so that
  // negative instants round toward the earlier second.
  const whole = Math.floor(epochMs);
  const subSecond = ((whole % 1000) + 1000) % 1000;
  const d = new Date(whole - subSecond);
  // toISOString always yields ".mmmZ"; remove the milliseconds and keep "Z".
  return d.toISOString().replace(/\.\d{3}Z$/, "Z");
}

const TIME_DELIMITER = /[T ]/;
const OFFSET_TAIL = /(?:[Zz]|[+-]\d{2}(?::?\d{2})?)$/;

// lib.parseISO interprets strings without an offset in the local time zone,
// but the spec requires UTC. Normalize every input to carry an explicit offset
// so the library takes its offset branch, which is zone-independent.
function toExplicitUtc(input: string): string {
  const delim = input.search(TIME_DELIMITER);
  if (delim === -1) {
    // Date-only input: midnight UTC.
    return `${input}T00:00:00Z`;
  }
  const timePart = input.slice(delim + 1);
  if (OFFSET_TAIL.test(timePart)) {
    return input;
  }
  // Time present without an offset: treat as UTC.
  return `${input}Z`;
}

export function solve(stamps: string[]): number[] {
  const epochs = stamps.map((raw) => {
    if (typeof raw !== "string") {
      throw new RangeError(`Invalid ISO 8601 date: ${String(raw)}`);
    }
    const date = lib.parseISO(toExplicitUtc(raw));
    const ms = date.getTime();
    if (Number.isNaN(ms)) {
      throw new RangeError(`Invalid ISO 8601 date: ${raw}`);
    }
    return ms;
  });
  return epochs.sort((a, b) => a - b);
}

export function solve(range: string): string | null {
  let result: any;
  try {
    result = lib.minVersion(range);
  } catch (_err) {
    // lib.minVersion throws on an invalid range expression
    return null;
  }

  if (!result) {
    return null;
  }

  const major: number = result.major;
  const minor: number = result.minor;
  const patch: number = result.patch;
  const prerelease: Array<string | number> = result.prerelease || [];

  let out = `${major}.${minor}.${patch}`;
  if (prerelease.length > 0) {
    out += "-" + prerelease.join(".");
  }
  return out;
}

