  // Build metadata never affects precedence, so compare the versions with
  // their build parts removed. A prerelease cannot contain '+', so the first
  // '+' always starts the build metadata.
  const stripBuild = (v: string): string => {
    const i = v.indexOf('+');
    return i === -1 ? v : v.slice(0, i);
