  // A version-like run: up to three dot-separated digit runs of 1-16 digits each.
  // Lookbehind/lookahead ensure we start and end on digit-run boundaries.
  const re = /(?<!\d)(\d{1,16})(?:\.(\d{1,16}))?(?:\.(\d{1,16}))?(?!\d)/;
