// Sine-derived constants: K[i] = floor(|sin(i + 1)| * 2^32)
const MD5_K: Uint32Array = (() => {
  const k = new Uint32Array(64);
  for (let i = 0; i < 64; i++) {
    k[i] = Math.floor(Math.abs(Math.sin(i + 1)) * 4294967296);
