// MD5 digest (RFC 1321) returning 16 bytes; used as the `hash` argument to lib.v35
function md5(msg: Uint8Array): Uint8Array {
  const len = msg.length;
  const padLen = Math.ceil((len + 9) / 64) * 64;
  const data = new Uint8Array(padLen);
  data.set(msg);
  data[len] = 0x80;

  const dv = new DataView(data.buffer);
  dv.setUint32(padLen - 8, (len * 8) >>> 0, true);
  dv.setUint32(padLen - 4, Math.floor(len / 0x20000000) >>> 0, true);

  let a0 = 0x67452301;
  let b0 = 0xefcdab89 | 0;
  let c0 = 0x98badcfe | 0;
  let d0 = 0x10325476;

  const M = new Uint32Array(16);

  for (let off = 0; off < padLen; off += 64) {
    for (let j = 0; j < 16; j++) {
      M[j] = dv.getUint32(off + j * 4, true);
    }

    let A = a0;
    let B = b0;
    let C = c0;
    let D = d0;

    for (let i = 0; i < 64; i++) {
      let F: number;
      let g: number;
      if (i < 16) {
        F = (B & C) | (~B & D);
        g = i;
      } else if (i < 32) {
        F = (D & B) | (~D & C);
        g = (5 * i + 1) & 15;
      } else if (i < 48) {
        F = B ^ C ^ D;
        g = (3 * i + 5) & 15;
      } else {
        F = C ^ (B | ~D);
