// Note: lib.isCreditCard is not used because its provider regexes are narrower than
// this spec (e.g. it rejects 19-digit Visa, 14-19 digit Diners, 17-19 digit JCB), so
// it would reject some numbers the spec considers valid. The prefix/length rules and
// the Luhn check are implemented directly instead.
export function solve(card: string): boolean {
  if (typeof card !== "string") return false;

  const s = card.replace(/[ -]+/g, "");
  if (!/^\d+$/.test(s)) return false;

  const n = s.length;

  // True if the first `k` digits form a number within [lo, hi].
  const inRange = (k: number, lo: number, hi: number): boolean => {
    if (s.length < k) return false;
    const v = Number(s.slice(0, k));
    return v >= lo && v <= hi;
  };

  const luhn = (digits: string): boolean => {
    let sum = 0;
    let double = false;
    for (let i = digits.length - 1; i >= 0; i--) {
      let d = digits.charCodeAt(i) - 48;
      if (double) {
        d *= 2;
        if (d > 9) d -= 9;
      }
      sum += d;
      double = !double;
    }
    return sum % 10 === 0;
  };

  const visa = s[0] === "4" && (n === 13 || n === 16 || n === 19);

  const mastercard =
    n === 16 && (inRange(2, 51, 55) || inRange(4, 2221, 2720));

  const amex = n === 15 && (inRange(2, 34, 34) || inRange(2, 37, 37));

  const discover =
    (n === 16 || n === 19) &&
    (s.startsWith("6011") ||
      inRange(6, 622126, 622925) ||
      inRange(3, 644, 649) ||
      inRange(2, 65, 65));

  const diners =
    n >= 14 &&
    n <= 19 &&
    (inRange(3, 300, 305) || inRange(2, 36, 36) || inRange(2, 38, 38));

  const jcb = n >= 16 && n <= 19 && inRange(4, 3528, 3589);

  const unionpay = n >= 16 && n <= 19 && inRange(2, 62, 62);

  const issuerMatch =
    visa || mastercard || amex || discover || diners || jcb || unionpay;

  return issuerMatch && luhn(s);
}

type Parsed = { core: [string, string, string]; pre: string[] };

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

function parse(v: string): Parsed {
  const m = SEMVER_RE.exec(v);
  if (!m) throw new TypeError(`Invalid semver version: ${v}`);
  return {
    core: [m[1], m[2], m[3]],
    pre: m[4] ? m[4].split(".") : [],
  };
}

// Numeric identifiers never have leading zeros (semver rule), so
// comparing by length and then lexicographically is exact and avoids overflow.
function cmpNumeric(x: string, y: string): number {
  if (x.length !== y.length) return x.length < y.length ? -1 : 1;
  return x < y ? -1 : x > y ? 1 : 0;
}

function cmpIdent(x: string, y: string): number {
  const xn = /^\d+$/.test(x);
  const yn = /^\d+$/.test(y);
  if (xn && yn) return cmpNumeric(x, y);
  if (xn) return -1; // numeric identifiers have lower precedence
  if (yn) return 1;
  return x < y ? -1 : x > y ? 1 : 0;
}

function cmpPre(p: string[], q: string[]): number {
  if (p.length === 0 && q.length === 0) return 0;
  if (p.length === 0) return 1; // release > prerelease
  if (q.length === 0) return -1;
  const n = Math.min(p.length, q.length);
  for (let i = 0; i < n; i++) {
    const c = cmpIdent(p[i], q[i]);
    if (c !== 0) return c;
  }
  return p.length === q.length ? 0 : p.length < q.length ? -1 : 1;
}

function compare(a: Parsed, b: Parsed): number {
  for (let i = 0; i < 3; i++) {
    const c = cmpNumeric(a.core[i], b.core[i]);
    if (c !== 0) return c;
  }
  return cmpPre(a.pre, b.pre);
}

const PARTS = ["major", "minor", "patch"] as const;

export function solve(a: string, b: string): string | null {
  const pa = parse(a);
  const pb = parse(b);

  const c = compare(pa, pb);
  if (c === 0) return null; // build metadata is never considered

  const [lo, hi] = c < 0 ? [pa, pb] : [pb, pa];
  const loPre = lo.pre.length > 0;
  const hiPre = hi.pre.length > 0;

  // Index of the highest differing core part (-1 if cores are equal).
  const idx = lo.core.findIndex((v, i) => v !== hi.core[i]);

  // Lower is a prerelease, higher is a release.
  if (loPre && !hiPre && idx === -1) {
    // Cores equal: classify by the lower's minor/patch being zero.
    const [, lm, lp] = lo.core;
    if (lm === "0" && lp === "0") return "major";
    if (lp === "0") return "minor";
    return "patch";
  }

  if (idx === -1) {
    // Cores equal, both prereleases (different prerelease tags).
    return "prerelease";
  }

  const part = PARTS[idx];
  return hiPre ? `pre${part}` : part;
}

export function solve(mac: string): boolean {
  // The library's colon/hyphen patterns check each separator independently,
  // so they accept mixed separators. Reject any string containing both.
  if (mac.includes(':') && mac.includes('-')) {
    return false;
  }
  return lib.isMACAddress(mac);
}

export function solve(issn: string): boolean {
  if (typeof issn !== 'string') return false;
  // Enforce the ISSN shape: NNNN-NNNC or NNNNNNNC, check character is a digit or X/x.
  if (!/^\d{4}-?\d{3}[\dXx]$/.test(issn)) return false;
  return lib.isISSN(issn);
}

export function solve(code: string): boolean {
  if (typeof code !== 'string' || !/^\d+$/.test(code)) return false;

  // EAN-8 and EAN-13: delegate to the library.
  if (code.length === 8 || code.length === 13) {
    return lib.isEAN(code);
  }

  // GTIN-14: the library's regex only covers EAN-8/EAN-13, so compute the check here.
  // Data digits are indices 0..12; the rightmost data digit (index 12) has weight 3,
  // and weights alternate 3,1 moving leftward.
  if (code.length === 14) {
    let sum = 0;
    for (let i = 0; i < 13; i++) {
      const digit = code.charCodeAt(i) - 48;
      sum += digit * (i % 2 === 0 ? 3 : 1);
    }
    const check = (10 - (sum % 10)) % 10;
    return check === code.charCodeAt(13) - 48;
  }

  return false;
}

export function solve(text: string, version?: 4 | 6): boolean {
  // Accepts only canonical decimal octets: 0-255, no leading zeros ("0" is fine).
  const canonicalOctets = (s: string): boolean =>
    s.split('.').every((p) => /^(0|[1-9][0-9]{0,2})$/.test(p) && Number(p) <= 255);

  const isV4 = (s: string): boolean =>
    lib.isIP(s, 4) && canonicalOctets(s);

  // Link-local unicast addresses are fe80::/10.
  const isLinkLocal = (addr: string): boolean => {
    const first = addr.split(':')[0];
    return /^[0-9a-fA-F]{1,4}$/.test(first) && (parseInt(first, 16) & 0xffc0) === 0xfe80;
  };

  const isV6 = (s: string): boolean => {
    let addr = s;
    const pct = s.indexOf('%');
    if (pct !== -1) {
      const zone = s.slice(pct + 1);
      addr = s.slice(0, pct);
      if (!/^[A-Za-z0-9]+$/.test(zone)) return false;
      if (!isLinkLocal(addr)) return false;
    }
    if (!lib.isIP(addr, 6)) return false;

    // The library may accept leading zeros in an embedded trailing IPv4 part;
    // reject those to match the canonical form.
    const tail = addr.slice(addr.lastIndexOf(':') + 1);
    if (tail.includes('.') && !canonicalOctets(tail)) return false;

    return true;
  };

  if (version === 4) return isV4(text);
  if (version === 6) return isV6(text);
  return isV4(text) || isV6(text);
}

export function solve(text: string): boolean {
  if (typeof text !== 'string') return false;

  // Structure: optional "(", latitude, comma, optional spaces, longitude, optional ")".
  // Numeric parts contain no commas, parentheses, or whitespace, so this rejects
  // DMS forms, space-only separators, and extra commas. Only spaces (not tabs or
  // other whitespace) are accepted after the comma.
  const match = /^(\(?)([^,()\s]+),[ ]*([^,()\s]+)(\)?)$/.exec(text);
  if (match === null) return false;

  const open = match[1];
  const latPart = match[2];
  const longPart = match[3];
  const close = match[4];

  // The parentheses must wrap the pair together: both or neither.
  if ((open === '') !== (close === '')) return false;

  // Normalize the separator to exactly ", " so the library's single-space
  // handling applies, then let the library validate the numeric ranges and format.
  const normalized = `${open}${latPart}, ${longPart}${close}`;
  return lib.isLatLong(normalized);
}

export function solve(a: string, b: string): number {
    return lib.distance(a, b);
}

declare const lib: {
  get(obj: unknown, pointer: string): unknown;
};

export function solve(doc: unknown, pointer: string): unknown {
  if (pointer === '') return doc;
  if (pointer[0] !== '/') {
    throw new Error('Invalid JSON Pointer: must be empty or start with "/".');
  }

  // Verify each step exists as an own property (or valid array index) so that
  // inherited members such as "constructor" or "length" are not reported.
  const tokens = pointer
    .slice(1)
    .split('/')
    .map((t) => t.replace(/~1/g, '/').replace(/~0/g, '~'));

  let current: unknown = doc;
  for (const token of tokens) {
    if (typeof current !== 'object' || current === null) return undefined;

    if (Array.isArray(current)) {
      if (!/^(0|[1-9]\d*)$/.test(token)) return undefined;
      const index = Number(token);
      if (index >= current.length) return undefined;
      current = current[index];
    } else {
      if (!Object.prototype.hasOwnProperty.call(current, token)) return undefined;
      current = (current as Record<string, unknown>)[token];
    }
  }

  return lib.get(doc, pointer);
}

export function solve(code: string): boolean {
  // Structure: 3 owner letters, category U/J/Z (any case), 6 serial digits, 1 check digit.
  // Matched against the original string so no case conversion can change its length.
  if (!/^[A-Za-z]{3}[UJZujz][0-9]{7}$/.test(code)) {
    return false;
  }
  // Uppercasing is now ASCII-only, so the library sees the expected 11 characters.
  return lib.isISO6346(code.toUpperCase());
}

export function solve(range: string): string | null {
  return lib.validRange(range);
}

export function solve(name: string): boolean {
  if (typeof name !== 'string') return false;

  // No trailing dot, non-empty, and at most 253 characters (code points)
  if (name.length === 0 || name.endsWith('.')) return false;
  if (Array.from(name).length > 253) return false;

  const labels = name.split('.');
  if (labels.length < 2) return false;

  // Structural checks delegated to the library. Length is checked below
  // by characters rather than UTF-16 units, so the library's length check is disabled.
  const ok = lib.isFQDN(name, {
    require_tld: true,
    allow_numeric_tld: false,
    allow_underscores: false,
    allow_trailing_dot: false,
    allow_wildcard: false,
    ignore_max_length: true,
  });
  if (!ok) return false;

  // Each label: 1–63 characters of letters, digits, or hyphens,
  // not starting or ending with a hyphen
  const labelRe = /^[\p{L}0-9-]+$/u;
  for (const label of labels) {
    const len = Array.from(label).length;
    if (len < 1 || len > 63) return false;
    if (!labelRe.test(label)) return false;
    if (label.startsWith('-') || label.endsWith('-')) return false;
  }

  // TLD: at least 2 characters, and either a punycode label (xn--...)
  // or consisting only of letters (international letters allowed)
  const tld = labels[labels.length - 1];
  if (Array.from(tld).length < 2) return false;

  if (/^xn--/i.test(tld)) {
    return /^xn--[a-z0-9-]+$/i.test(tld);
  }

  return /^\p{L}+$/u.test(tld);
}

export function solve(uuid: string): string | null {
    if (typeof uuid !== 'string') return null;
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(uuid)) return null;

    // The variant digit is the first character of the fourth group (index 19).
    const variant = uuid[19].toLowerCase();
    if (variant !== '8' && variant !== '9' && variant !== 'a' && variant !== 'b') return null;

    return (lib.v1ToV6(uuid.toLowerCase()) as string).toLowerCase();
}

export function solve(version: string, range: string): boolean {
  return lib.ltr(version, range);
}

export function solve(versions: string[], range: string): string | null {
  if (!Array.isArray(versions) || typeof range !== 'string') {
    return null;
  }
  // Non-string entries are invalid versions and must be skipped.
  const candidates = versions.filter((v): v is string => typeof v === 'string');
  return lib.minSatisfying(candidates, range);
}

export function solve(egn: string): boolean {
  if (typeof egn !== "string" || !/^[0-9]{10}$/.test(egn)) {
    return false;
  }

  const d = egn.split("").map((c) => c.charCodeAt(0) - 48);

  const yy = d[0] * 10 + d[1];
  let mm = d[2] * 10 + d[3];
  const dd = d[4] * 10 + d[5];

  let century: number;
  if (mm >= 1 && mm <= 12) {
    century = 1900;
  } else if (mm >= 21 && mm <= 32) {
    century = 1800;
    mm -= 20;
  } else if (mm >= 41 && mm <= 52) {
    century = 2000;
    mm -= 40;
  } else if (mm >= 61 && mm <= 72) {
    century = 2100;
    mm -= 60;
  } else {
    return false;
  }

  const year = century + yy;
  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  if (dd < 1 || dd > daysInMonth[mm - 1]) {
    return false;
  }

  const weights = [2, 4, 8, 5, 10, 9, 7, 3, 6];
  let sum = 0;
  for (let i = 0; i < 9; i++) {
    sum += d[i] * weights[i];
  }

  let check = sum % 11;
  if (check === 10) {
    check = 0;
  }

  return check === d[9];
}

export function solve(sub: string, sup: string): boolean {
  return lib.subset(sub, sup)
}

export function solve(id: string): boolean {
  // Remove slashes and backslashes
  const s = id.replace(/[\/\\]/g, '');

  // Must be exactly 11 digits
  if (!/^[0-9]{11}$/.test(s)) return false;

  // First digit must not be 0
  if (s[0] === '0') return false;

  // Among the first 10 digits, exactly one digit occurs 2 or 3 times,
  // and no other digit occurs more than once
  const counts: number[] = new Array(10).fill(0);
  for (let i = 0; i < 10; i++) {
    counts[Number(s[i])]++;
  }

  let repeated = 0;
  for (const n of counts) {
    if (n >= 4) return false;
    if (n === 2 || n === 3) repeated++;
  }
  if (repeated !== 1) return false;

  // Check digit via Verhoeff algorithm
  return lib.verhoeffCheck(s);
}

export function solve(installed: string[], range: string): string | null {
  // Strict SemVer 2.0.0 pattern (optional leading "v", surrounding whitespace allowed).
  const SEMVER =
    /^\s*v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?\s*$/;

  // Ignore anything that is not a valid version.
  const valid = installed.filter((v) => SEMVER.test(v));

  // Delegate range parsing, prerelease handling, and max selection to the library.
  return lib.maxSatisfying(valid, range, undefined);
}

export function solve(obj: object, updates: [string | (string | number)[], unknown][]): object {
  for (const [path, value] of updates) {
    lib.set(obj, path, value);
  }
  return obj;
}

export function solve<T>(value: T): T {
  return lib.cloneDeep(value) as T;
}

const ALLOWED_PROTOCOLS: string[] = ['http', 'https'];

// Options forwarded to lib.isURL. Copied on each call because the library
// merges defaults into the options object it receives.
function libOptions(): Record<string, unknown> {
  return {
    protocols: [...ALLOWED_PROTOCOLS],
    require_protocol: true,
    require_valid_protocol: true,
    require_host: true,
    require_tld: true,
    require_port: false,
    allow_protocol_relative_urls: false,
    allow_underscores: false,
    allow_trailing_dot: false,
    allow_fragments: true,
    allow_query_components: true,
    validate_length: true,
  };
}

// Extracts the hostname (without userinfo or port) from an http(s) URL.
// Returns null for IPv6 literals or when the URL shape does not match.
function extractHostname(url: string): string | null {
  const match = /^https?:\/\/([^\/?#]*)/i.exec(url);
  if (!match) {
    return null;
  }

  let authority = match[1];

  const at = authority.lastIndexOf('@');
  if (at !== -1) {
    authority = authority.slice(at + 1);
  }

  if (authority.startsWith('[')) {
    return null;
  }

  const colon = authority.indexOf(':');
  const host = colon === -1 ? authority : authority.slice(0, colon);

  return host.length > 0 ? host : null;
}

// True only for a fully qualified domain name with a real TLD.
// Rejects single-label hosts such as "localhost" and bare IPv4 addresses,
// since the final label of an IPv4 address is numeric.
function isFQDN(hostname: string): boolean {
  if (hostname.length === 0 || hostname.length > 253) {
    return false;
  }

  const labels = hostname.split('.');
  if (labels.length < 2) {
    return false;
  }

  for (const label of labels) {
    if (label.length === 0 || label.length > 63) {
      return false;
    }
    if (!/^[A-Za-z0-9-]+$/.test(label)) {
      return false;
    }
    if (label.startsWith('-') || label.endsWith('-')) {
      return false;
    }
  }

  const tld = labels[labels.length - 1];
  return /^[A-Za-z]{2,63}$/.test(tld) || /^xn--[A-Za-z0-9-]+$/.test(tld);
}

export function solve(urls: string[]): string[] {
  return urls.filter((url) => {
    // lib.isURL throws on non-strings, so guard first.
    if (typeof url !== 'string') {
      return false;
    }

    // Protocol, spaces, and general URL validity are handled by the library.
    if (!lib.isURL(url, libOptions())) {
      return false;
    }

    const hostname = extractHostname(url);
    return hostname !== null && isFQDN(hostname);
  });
}

export function solve(emails: string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];

  const stripSuffix = (local: string): string => {
    const plus = local.indexOf("+");
    return plus < 0 ? local : local.slice(0, plus);
  };

  for (const raw of emails) {
    const email = raw.toLowerCase();
    const at = email.lastIndexOf("@");
    let canonical: string;

    if (at < 0) {
      canonical = email;
    } else {
      let local = email.slice(0, at);
      let domain = email.slice(at + 1);

      if (domain === "gmail.com" || domain === "googlemail.com") {
        local = stripSuffix(local);
        // Remove single dots only; keep runs of two or more dots as they are.
        local = local.replace(/\.+/g, (run) => (run.length === 1 ? "" : run));
        domain = "gmail.com";
      } else if (
        domain === "outlook.com" ||
        domain === "hotmail.com" ||
        domain === "live.com"
      ) {
        local = stripSuffix(local);
      }

      canonical = `${local}@${domain}`;
    }

    if (!seen.has(canonical)) {
      seen.add(canonical);
      result.push(canonical);
    }
  }

  return result;
}

export function solve(id: string): boolean {
  const match = /^(\d{2})(\d{2})(\d{2})\/?(\d{3,4})$/.exec(id);
  if (!match) return false;

  const yy = Number(match[1]);
  let month = Number(match[2]);
  const day = Number(match[3]);
  const serial = match[4];

  let year: number;
  if (serial.length === 4) {
    // 10-digit form: two-digit year below 54 is 20YY, otherwise 19YY
    year = yy < 54 ? 2000 + yy : 1900 + yy;
  } else {
    // 9-digit form: only for numbers issued before 1954, serial must not be 000
    if (yy >= 54) return false;
    if (serial === "000") return false;
    year = 1900 + yy;
  }

  // Month offsets: +50 for women; +20 (men) and +70 (women) from 2004 onward
  let needs2004 = false;
  if (month >= 71) {
    month -= 70;
    needs2004 = true;
  } else if (month >= 51) {
    month -= 50;
  } else if (month >= 21) {
    month -= 20;
    needs2004 = true;
  }

  if (needs2004 && year < 2004) return false;
  if (month < 1 || month > 12) return false;

  const isLeap = (y: number): boolean =>
    (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;

  const daysInMonth = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  let maxDay = daysInMonth[month - 1];
  if (month === 2 && isLeap(year)) maxDay = 29;
  if (day < 1 || day > maxDay) return false;

  if (serial.length === 4) {
    // Check digit: first 9 digits mod 11; remainder 10 requires check digit 0
    const digits = match[1] + match[2] + match[3] + serial;
    const base = Number(digits.slice(0, 9));
    const check = Number(digits.slice(9, 10));
    const r = base % 11;
    const expected = r === 10 ? 0 : r;
    return check === expected;
  }

  return true;
}

export function solve(word: string, dictionary: string[]): string {
    return lib.closest(word, dictionary);
}

export function solve(text: string): string {
    // Encode the string as UTF-8 manually (no TextEncoder, which is not ECMAScript).
    const bytes: number[] = [];
    for (let i = 0; i < text.length; i++) {
        let cp = text.charCodeAt(i);
        if (cp >= 0xd800 && cp <= 0xdbff) {
            // High surrogate: combine with a following low surrogate if present.
            const lo = i + 1 < text.length ? text.charCodeAt(i + 1) : 0;
            if (lo >= 0xdc00 && lo <= 0xdfff) {
                cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
                i++;
            } else {
                cp = 0xfffd; // lone high surrogate
            }
        } else if (cp >= 0xdc00 && cp <= 0xdfff) {
            cp = 0xfffd; // lone low surrogate
        }

        if (cp < 0x80) {
            bytes.push(cp);
        } else if (cp < 0x800) {
            bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            bytes.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            bytes.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    // Delegate the MD5 computation to the library.
    const digest = lib.md5(new Uint8Array(bytes));

    // Convert the 16 digest bytes to 32 lowercase hex characters.
    return Array.from(digest as ArrayLike<number>, (b: number) =>
        b.toString(16).padStart(2, "0")
    ).join("");
}

export function solve(nodes: string[], edges: [string, string][]): string[] {
  // lib.toposort throws an Error for unknown nodes and for cyclic dependencies.
  return lib.toposort(nodes, edges);
}

export function solve(text: string): number[] {
  if (text.length % 4 !== 0) {
    throw new Error("Invalid base64 input: length must be a multiple of 4");
  }
  return Array.from(lib.toByteArray(text));
}

export function solve(epochMs: number): string {
  // Floor to whole seconds so negative fractional instants round toward the past.
  const wholeSeconds = Math.floor(epochMs / 1000) * 1000;
  // toISOString throws a RangeError for invalid times (NaN, Infinity, out of range).
  const iso = new Date(wholeSeconds).toISOString();
  // Remove the ".000" milliseconds suffix, keeping the trailing "Z".
  return iso.replace(/\.\d{3}Z$/, "Z");
}

export function solve(name: string, namespace: string): string {
    const nsHex = namespace.replace(/-/g, "");
    if (!/^[0-9a-fA-F]{32}$/.test(nsHex)) {
        throw new Error("invalid namespace UUID");
    }

    const nameBytes = utf8Encode(name);
    const data = new Uint8Array(16 + nameBytes.length);
    for (let i = 0; i < 16; i++) {
        data[i] = parseInt(nsHex.substring(i * 2, i * 2 + 2), 16);
    }
    data.set(nameBytes, 16);

    const hash = lib.sha1(data);
    const out = hash.slice(0, 16);

    // Set version (5) and RFC 4122 variant bits.
    out[6] = (out[6] & 0x0f) | 0x50;
    out[8] = (out[8] & 0x3f) | 0x80;

    let hex = "";
    for (let i = 0; i < 16; i++) {
        hex += (out[i] < 16 ? "0" : "") + out[i].toString(16);
    }

    return (
        hex.substring(0, 8) + "-" +
        hex.substring(8, 12) + "-" +
        hex.substring(12, 16) + "-" +
        hex.substring(16, 20) + "-" +
        hex.substring(20, 32)
    );
}

function utf8Encode(s: string): Uint8Array {
    const out: number[] = [];
    for (const ch of s) {
        let cp = ch.codePointAt(0)!;
        // Lone surrogates are replaced with U+FFFD, matching standard UTF-8 encoders.
        if (cp >= 0xd800 && cp <= 0xdfff) {
            cp = 0xfffd;
        }
        if (cp < 0x80) {
            out.push(cp);
        } else if (cp < 0x800) {
            out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            out.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            out.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }
    return Uint8Array.from(out);
}

const DAY_MS = 86400000;
const MIN_MS = 60000;

// Pattern groups:
// 1: year
// 2-3: calendar month, day
// 4-5: ISO week, weekday
// 6: ordinal day
// 7-8: hour, minute
// 9: second
// 10: fractional seconds
// 11: offset (Z or ±hh:mm)
const PATTERN =
  /^(\d{4})(?:-(\d{2})-(\d{2})|-W(\d{2})-(\d)|-(\d{3}))(?:T(\d{2}):(\d{2})(?::(\d{2})(?:[.,](\d+))?)?(Z|[+-]\d{2}:\d{2})?)?$/;

function invalid(input: unknown): RangeError {
  return new RangeError(`Invalid ISO 8601 date: ${String(input)}`);
}

/** UTC midnight epoch ms for the given calendar date; safe for years 0-99. */
function utcMidnight(year: number, month0: number, day: number): number {
  const dt = new Date(0);
  dt.setUTCFullYear(year, month0, day);
  dt.setUTCHours(0, 0, 0, 0);
  return dt.getTime();
}

function isLeapYear(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysInMonth(year: number, month: number): number {
  if (month === 2) return isLeapYear(year) ? 29 : 28;
  return month === 4 || month === 6 || month === 9 || month === 11 ? 30 : 31;
}

function parseOne(input: string): number {
  if (typeof input !== "string") {
    throw invalid(input);
  }

  const m = PATTERN.exec(input);
  if (!m) {
    throw invalid(input);
  }

  const year = Number(m[1]);
  let dayMs: number;

  if (m[2] !== undefined) {
    // Calendar date
    const month = Number(m[2]);
    const day = Number(m[3]);
    if (month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month)) {
      throw invalid(input);
    }
    dayMs = utcMidnight(year, month - 1, day);
  } else if (m[4] !== undefined) {
    // ISO week date
    const week = Number(m[4]);
    const weekday = Number(m[5]);
    if (week < 1 || week > 53 || weekday < 1 || weekday > 7) {
      throw invalid(input);
    }
    const jan4 = utcMidnight(year, 0, 4); // always in ISO week 1
    const jan4Dow = (new Date(jan4).getUTCDay() + 6) % 7; // 0 = Monday
    const week1Monday = jan4 - jan4Dow * DAY_MS;
    dayMs = week1Monday + ((week - 1) * 7 + (weekday - 1)) * DAY_MS;
    // The ISO week belongs to `year` only if its Thursday falls in `year`
    // (rejects week 53 in years that only have 52 weeks).
    const thursday = dayMs + 3 * DAY_MS;
    if (new Date(thursday).getUTCFullYear() !== year) {
      throw invalid(input);
    }
  } else {
    // Ordinal date
    const ordinal = Number(m[6]);
    const daysInYear = isLeapYear(year) ? 366 : 365;
    if (ordinal < 1 || ordinal > daysInYear) {
      throw invalid(input);
    }
    dayMs = utcMidnight(year, 0, 1) + (ordinal - 1) * DAY_MS;
  }

  // Time of day (optional; defaults to 00:00:00.000)
  let timeMs = 0;
  if (m[7] !== undefined) {
    const hour = Number(m[7]);
    const minute = Number(m[8]);
    const second = m[9] !== undefined ? Number(m[9]) : 0;
    const fraction = m[10] || "";

    if (minute > 59 || second > 59) {
      throw invalid(input);
    }
    // 24:00:00 is permitted by ISO 8601 and denotes the end of the day.
    if (
      hour > 24 ||
      (hour === 24 && (minute !== 0 || second !== 0 || /[1-9]/.test(fraction)))
    ) {
      throw invalid(input);
    }

    const millis = Number((fraction + "000").slice(0, 3));
    timeMs = ((hour * 60 + minute) * 60 + second) * 1000 + millis;
  }

  // Offset (optional; absent means UTC)
  let offsetMinutes = 0;
  const zone = m[11];
  if (zone !== undefined && zone !== "Z") {
    const sign = zone[0] === "-" ? -1 : 1;
    const offH = Number(zone.slice(1, 3));
    const offM = Number(zone.slice(4, 6));
    if (offH > 23 || offM > 59) {
      throw invalid(input);
    }
    offsetMinutes = sign * (offH * 60 + offM);
  }

  return dayMs + timeMs - offsetMinutes * MIN_MS;
}

export function solve(stamps: string[]): number[] {
  const parsed = stamps.map(parseOne);
  return parsed.sort((a, b) => a - b);
}

export function solve(a: string, b: string): boolean {
  return lib.intersects(a, b);
}

export function solve(range: string): string | null {
  try {
    const minver = lib.minVersion(range);
    return minver ? minver.format() : null;
  } catch (_err) {
    // lib.minVersion throws on malformed ranges; those map to null.
    return null;
  }
}

export function solve(version: string, range: string): boolean {
  return lib.gtr(version, range);
}

export function solve(versions: string[]): string[] {
  return [...versions].sort((a, b) => {
    const c = lib.compare(a, b);
    if (c !== 0) return c;
    // Precedence ties (e.g. differing only in build metadata): order by full string.
    return a < b ? -1 : a > b ? 1 : 0;
  });
}

export function solve(
  version: string,
  kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease',
  id?: string
): string | null {
  return lib.inc(version, kind, id);
}

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function solve(name: string, namespace: string): string {
  if (typeof namespace !== "string" || !UUID_RE.test(namespace)) {
    throw new TypeError("namespace is not a valid UUID");
  }
  return lib.v3(name, namespace).toLowerCase();
}

type Parsed = { major: number; minor: number; patch: number; pre: string };

function parseVersion(v: string): Parsed {
  const m = /^[v=\s]*(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+[0-9A-Za-z.-]+)?\s*$/.exec(v.trim());
  if (!m) throw new TypeError(`Invalid version: ${v}`);
  return { major: Number(m[1]), minor: Number(m[2]), patch: Number(m[3]), pre: m[4] ?? '' };
}

function cmpCore(x: Parsed, y: Parsed): number {
  return (x.major - y.major) || (x.minor - y.minor) || (x.patch - y.patch);
}

export function solve(a: string, b: string): string | null {
  const result = lib.diff(a, b);
  if (result === null) return null;

  const pa = parseVersion(a);
  const pb = parseVersion(b);

  // Determine lower and higher versions.
  let low: Parsed;
  let high: Parsed;
  const cmp = cmpCore(pa, pb);
  if (cmp < 0) {
    low = pa;
    high = pb;
  } else if (cmp > 0) {
    low = pb;
    high = pa;
  } else {
    // Cores are equal: a prerelease is lower than a release.
    if (pa.pre && !pb.pre) {
      low = pa;
      high = pb;
    } else if (pb.pre && !pa.pre) {
      low = pb;
      high = pa;
    } else {
      // Both prerelease (or otherwise identical cores): lib result stands.
      return result;
    }
  }

  // Prerelease -> release where the lower is X.0.0-pre and the major is the
  // same: the change is the highest differing part of minor/patch rather than
  // the lib's unconditional "major".
  if (
    low.pre &&
    !high.pre &&
    low.minor === 0 &&
    low.patch === 0 &&
    high.major === low.major &&
    (high.minor !== 0 || high.patch !== 0)
  ) {
    return high.minor !== low.minor ? 'minor' : 'patch';
  }

  return result;
}

export function solve(text: string): string {
  // Manually UTF-8 encode, replacing lone surrogates with U+FFFD (as TextEncoder does).
  const out: number[] = [];
  for (const ch of text) {
    let cp = ch.codePointAt(0) ?? 0xfffd;
    if (cp >= 0xd800 && cp <= 0xdfff) cp = 0xfffd;
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }

  const digest = lib.sha1(Uint8Array.from(out));

  let hex = "";
  for (let i = 0; i < digest.length; i++) {
    hex += digest[i].toString(16).padStart(2, "0");
  }
  return hex;
}

export function solve(text: string): string | null {
  // Same pattern lib.coerce uses, so this locates the same first run it would.
  const m = /(^|[^\d])(\d{1,16})(?:\.(\d{1,16}))?(?:\.(\d{1,16}))?(?:$|[^\d])/.exec(text);
  if (!m) return null;

  const parts = [m[2], m[3] ?? "0", m[4] ?? "0"];

  // Leading zero in any number of the first run means null; no later run is tried.
  if (parts.some((p) => p.length > 1 && p[0] === "0")) return null;

  try {
    const v = lib.coerce(text);
    if (v) return v.version;
    return null;
  } catch {
    // lib.coerce throws for components above Number.MAX_SAFE_INTEGER.
    // The digits are already canonical here (no leading zeros), so build the string directly.
    return `${parts[0]}.${parts[1]}.${parts[2]}`;
  }
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  if (version === undefined) {
    return lib.isISBN(isbn);
  }
  return lib.isISBN(isbn, { version });
}

export function solve(iban: string): boolean {
  // Ignore spaces (and other whitespace) and hyphens, then normalise letters to uppercase.
  const normalized = iban.replace(/[\s-]/g, "").toUpperCase();
  return lib.isIBAN(normalized);
}

export function solve(mac: string): boolean {
  if (!lib.isMACAddress(mac)) {
    return false;
  }
  // The library's per-octet `[:-]` pattern accepts mixed separators,
  // so reject any string that uses both ':' and '-'.
  return !(mac.includes(":") && mac.includes("-"));
}

export function solve(isin: string): boolean {
  // Format: 2 uppercase letters, 9 uppercase alphanumerics, 1 digit check digit
  if (!/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(isin)) {
    return false;
  }

  // Convert letters to numbers (A=10 ... Z=35)
  const digits = isin.replace(/[A-Z]/g, (c: string) =>
    String(c.charCodeAt(0) - 55)
  );

  // Validate the expanded digit string with the Luhn algorithm
  return !!lib.isLuhnNumber(digits);
}

export function solve(text: string): boolean {
  let s = text;

  // Optional single pair of parentheses wrapping the whole pair.
  if (s.startsWith("(") && s.endsWith(")")) {
    s = s.slice(1, -1);
  } else if (s.startsWith("(") || s.endsWith(")")) {
    return false;
  }

  // Number: optional sign, integer digits, optional decimal fraction.
  // Separator: comma followed by optional spaces (none before the comma).
  const num = "[+-]?\\d+(?:\\.\\d+)?";
  const re = new RegExp(`^(${num}),[ ]*(${num})$`);
  const m = re.exec(s);
  if (!m) {
    return false;
  }

  const lat = Number(m[1]);
  const lon = Number(m[2]);

  return lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180;
}

// lib.isCreditCard is not used: its built-in issuer patterns do not match this
// spec (e.g. Discover 622126–622925/644–649, Diners 14–19 digits, UnionPay 62),
// so relying on it would reject valid cards. Rules and Luhn are implemented directly.
export function solve(card: string): boolean {
  const s = card.replace(/[ -]/g, '');
  if (!/^\d+$/.test(s)) return false;

  const n = s.length;
  const p2 = Number(s.slice(0, 2));
  const p3 = Number(s.slice(0, 3));
  const p4 = Number(s.slice(0, 4));
  const p6 = Number(s.slice(0, 6));

  const issuerOk =
    // Visa
    (s[0] === '4' && (n === 13 || n === 16 || n === 19)) ||
    // Mastercard
    (n === 16 && ((p2 >= 51 && p2 <= 55) || (p4 >= 2221 && p4 <= 2720))) ||
    // American Express
    (n === 15 && (p2 === 34 || p2 === 37)) ||
    // Discover
    ((n === 16 || n === 19) &&
      (s.startsWith('6011') ||
        (p6 >= 622126 && p6 <= 622925) ||
        (p3 >= 644 && p3 <= 649) ||
        p2 === 65)) ||
    // Diners Club
    (n >= 14 && n <= 19 &&
      ((p3 >= 300 && p3 <= 305) || p2 === 36 || p2 === 38)) ||
    // JCB
    (n >= 16 && n <= 19 && p4 >= 3528 && p4 <= 3589) ||
    // UnionPay
    (n >= 16 && n <= 19 && p2 === 62);

  if (!issuerOk) return false;

  // Luhn check
  let sum = 0;
  for (let i = n - 1, k = 0; i >= 0; i--, k++) {
    let d = s.charCodeAt(i) - 48;
    if (k % 2 === 1) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
  }
  return sum % 10 === 0;
}

export function solve(code: string): boolean {
  if (typeof code !== 'string' || !/^\d+$/.test(code)) return false;

  const n = code.length;

  // lib.isEAN covers EAN-8 and EAN-13.
  if (n === 8 || n === 13) return lib.isEAN(code);

  // lib.isEAN's regex rejects 14 digits, so GTIN-14 is checked here
  // with the same weighting: 3 for the rightmost data digit, then alternating 1, 3, ...
  if (n === 14) {
    let sum = 0;
    for (let i = 0; i < 13; i++) {
      const digit = code.charCodeAt(i) - 48;
      const fromRight = 12 - i;
      sum += digit * (fromRight % 2 === 0 ? 3 : 1);
    }
    const check = (10 - (sum % 10)) % 10;
    return check === code.charCodeAt(13) - 48;
  }

  return false;
}

export function solve(issn: string): boolean {
  if (typeof issn !== 'string') {
    return false;
  }
  return lib.isISSN(issn);
}

export function solve(text: string, version?: 4 | 6): boolean {
  if (typeof text !== 'string') return false;

  // Strict dotted-quad check: exactly four decimal octets 0-255, no leading zeros.
  const hasStrictOctets = (s: string): boolean => {
    const parts = s.split('.');
    return parts.length === 4 && parts.every(
      (p) => /^(0|[1-9][0-9]{0,2})$/.test(p) && Number(p) <= 255
    );
  };

  const isV4 = (s: string): boolean =>
    lib.isIP(s, { version: 4 }) && hasStrictOctets(s);

  const isV6 = (s: string): boolean => {
    let addr = s;
    let zone: string | undefined;

    // Split off an optional zone index.
    const pct = s.indexOf('%');
    if (pct !== -1) {
      addr = s.slice(0, pct);
      zone = s.slice(pct + 1);
      if (!/^[A-Za-z0-9]+$/.test(zone)) return false;
    }

    // Heavy lifting: base IPv6 syntax check.
    if (!lib.isIP(addr, { version: 6 })) return false;

    // Enforce strict IPv4 rules on an embedded trailing IPv4 part.
    const tail = addr.slice(addr.lastIndexOf(':') + 1);
    if (tail.includes('.') && !hasStrictOctets(tail)) return false;

    // A zone index is only allowed on link-local addresses (fe80::/10).
    if (zone !== undefined) {
      const first = addr.split(':')[0];
      if (!/^[0-9A-Fa-f]{1,4}$/.test(first)) return false;
      const n = parseInt(first, 16);
      if (!(n >= 0xfe80 && n <= 0xfebf)) return false;
    }

    return true;
  };

  const v4ok = (version === undefined || version === 4) && isV4(text);
  const v6ok = (version === undefined || version === 6) && isV6(text);

  return v4ok || v6ok;
}

export function solve(a: string, b: string): number {
    return lib.distance(a, b);
}

export function solve(doc: unknown, pointer: string): unknown {
  // The empty pointer refers to the whole document, including primitives.
  if (pointer === '') return doc;

  if (pointer[0] !== '/') {
    throw new Error('Invalid JSON Pointer: must be empty or start with "/".');
  }

  // lib.get throws on non-objects and on null, so a non-empty pointer
  // cannot resolve against them. Treat that as a missing step.
  if (doc === null || typeof doc !== 'object') return undefined;

  return lib.get(doc, pointer);
}

export function solve(range: string): string | null {
  return lib.validRange(range);
}

export function solve(version: string, range: string): boolean {
  return lib.ltr(version, range);
}

export function solve(code: string): boolean {
  if (typeof code !== 'string') return false;
  // Enforce the exact shape with ASCII-only classes so that characters whose
  // toUpperCase() maps to A-Z (e.g. dotless "ı" or long "ſ") are rejected.
  if (!/^[A-Za-z]{3}[UJZujz][0-9]{7}$/.test(code)) return false;
  return lib.isISO6346(code);
}

const LABEL_CHARS = /^[\p{L}\p{M}\p{Nd}-]+$/u;
const LETTERS_ONLY = /^[\p{L}\p{M}]+$/u;
const PUNYCODE_TLD = /^xn--[a-z0-9-]+$/i;

const FQDN_OPTIONS = {
  require_tld: true,
  allow_underscores: false,
  allow_trailing_dot: false,
  allow_numeric_tld: false,
  allow_wildcard: false,
  ignore_max_length: false,
};

function codePointLength(s: string): number {
  return Array.from(s).length;
}

export function solve(name: string): boolean {
  if (typeof name !== "string") return false;
  if (codePointLength(name) > 253) return false;
  if (name.endsWith(".")) return false;

  // Heavy lifting: structural and character checks from the library.
  if (!lib.isFQDN(name, FQDN_OPTIONS)) return false;

  const labels = name.split(".");
  if (labels.length < 2) return false;

  for (const label of labels) {
    const length = codePointLength(label);
    if (length < 1 || length > 63) return false;
    if (!LABEL_CHARS.test(label)) return false;
    if (label.startsWith("-") || label.endsWith("-")) return false;
  }

  const tld = labels[labels.length - 1];
  if (codePointLength(tld) < 2) return false;
  if (!(LETTERS_ONLY.test(tld) || PUNYCODE_TLD.test(tld))) return false;

  return true;
}

export function solve(uuid: string): string | null {
  const pattern =
    /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$/;

  if (typeof uuid !== 'string' || !pattern.test(uuid)) {
    return null;
  }

  const result: string = lib.v1ToV6(uuid.toLowerCase());
  return result.toLowerCase();
}

export function solve(versions: string[], range: string): string | null {
  return lib.minSatisfying(versions, range);
}

export function solve(egn: string): boolean {
  if (typeof egn !== "string" || !/^\d{10}$/.test(egn)) {
    return false;
  }

  const d = egn.split("").map((c) => c.charCodeAt(0) - 48);

  const yy = d[0] * 10 + d[1];
  const mm = d[2] * 10 + d[3];
  const dd = d[4] * 10 + d[5];

  let century: number;
  let month: number;

  if (mm >= 1 && mm <= 12) {
    century = 1900;
    month = mm;
  } else if (mm >= 21 && mm <= 32) {
    century = 1800;
    month = mm - 20;
  } else if (mm >= 41 && mm <= 52) {
    century = 2000;
    month = mm - 40;
  } else if (mm >= 61 && mm <= 72) {
    century = 2100;
    month = mm - 60;
  } else if (mm >= 81 && mm <= 92) {
    century = 2200;
    month = mm - 80;
  } else {
    return false;
  }

  const year = century + yy;

  const isLeap = (y: number): boolean =>
    (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;

  const daysInMonth = (y: number, m: number): number => {
    switch (m) {
      case 2:
        return isLeap(y) ? 29 : 28;
      case 4:
      case 6:
      case 9:
      case 11:
        return 30;
      default:
        return 31;
    }
  };

  if (dd < 1 || dd > daysInMonth(year, month)) {
    return false;
  }

  const weights = [2, 4, 8, 5, 10, 9, 7, 3, 6];
  let sum = 0;
  for (let i = 0; i < 9; i++) {
    sum += d[i] * weights[i];
  }
  let check = sum % 11;
  if (check === 10) {
    check = 0;
  }

  return check === d[9];
}

const SEMVER_RE = /^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][a-zA-Z0-9-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][a-zA-Z0-9-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/

export function solve(installed: string[], range: string): string | null {
  const valid = installed.filter((v) => typeof v === 'string' && SEMVER_RE.test(v))
  return lib.maxSatisfying(valid, range)
}

export function solve(obj: object, updates: [string | (string | number)[], unknown][]): object {
  for (const [path, value] of updates) {
    lib.set(obj, path, value);
  }
  return obj;
}

export function solve(id: string): boolean {
  const match = /^(\d{2})(\d{2})(\d{2})\/?(\d{3,4})$/.exec(id);
  if (!match) return false;

  const yy = Number(match[1]);
  let mm = Number(match[2]);
  const dd = Number(match[3]);
  const tail = match[4];
  const isTenDigit = tail.length === 4;

  let year: number;
  if (isTenDigit) {
    // Choice: two-digit year below 54 is 20YY, otherwise 19YY.
    year = yy < 54 ? 2000 + yy : 1900 + yy;
  } else {
    // 9-digit form: only for numbers issued before 1954.
    if (yy >= 54) return false;
    year = 1900 + yy;
    // Serial number must not be 000.
    if (Number(tail) === 0) return false;
  }

  // Month decoding: women +50, from 2004 men +20 and women +70.
  let needsPost2004 = false;
  if (mm >= 71) {
    mm -= 70;
    needsPost2004 = true;
  } else if (mm >= 51) {
    mm -= 50;
  } else if (mm >= 21) {
    mm -= 20;
    needsPost2004 = true;
  }
  if (needsPost2004 && year < 2004) return false;
  if (mm < 1 || mm > 12) return false;

  // Day validity, including leap years.
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[mm - 1]) return false;

  if (isTenDigit) {
    // Check digit: remainder of first 9 digits mod 11; 10 maps to check digit 0.
    const nine = Number(match[1] + match[2] + match[3] + tail.slice(0, 3));
    const r = nine % 11;
    const expected = r === 10 ? 0 : r;
    return Number(tail[3]) === expected;
  }

  return true;
}

export function solve<T>(value: T): T {
  return lib.cloneDeep(value) as T;
}

export function solve(id: string): boolean {
  // Remove slashes and backslashes
  const s = id.replace(/[\/\\]/g, '');

  // Must be exactly 11 digits, first digit not zero
  if (!/^[0-9]{11}$/.test(s)) return false;
  if (s[0] === '0') return false;

  // Repetition rule on the first 10 digits:
  // exactly one digit occurs 2 or 3 times, all others at most once
  const counts: number[] = new Array(10).fill(0);
  for (let i = 0; i < 10; i++) {
    counts[Number(s[i])]++;
  }
  const repeated = counts.filter((c) => c > 1);
  if (repeated.length !== 1) return false;
  if (repeated[0] !== 2 && repeated[0] !== 3) return false;

  // Check digit (Verhoeff) over all 11 digits
  return lib.verhoeffCheck(s);
}

export function solve(emails: string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];

  for (const raw of emails) {
    const canon = canonicalize(raw);
    if (!seen.has(canon)) {
      seen.add(canon);
      result.push(canon);
    }
  }

  return result;
}

function stripPlusSuffix(local: string): string {
  const plus = local.indexOf("+");
  return plus >= 0 ? local.slice(0, plus) : local;
}

function canonicalize(email: string): string {
  const lower = email.toLowerCase();
  const at = lower.lastIndexOf("@");
  if (at < 0) {
    return lower;
  }

  let local = lower.slice(0, at);
  let domain = lower.slice(at + 1);

  if (domain === "gmail.com" || domain === "googlemail.com") {
    local = stripPlusSuffix(local);
    // Remove single dots only; keep runs of two or more dots.
    local = local.replace(/\.+/g, (run) => (run.length >= 2 ? run : ""));
    domain = "gmail.com";
  } else if (
    domain === "outlook.com" ||
    domain === "hotmail.com" ||
    domain === "live.com"
  ) {
    local = stripPlusSuffix(local);
  }

  return `${local}@${domain}`;
}

const URL_OPTIONS = {
  protocols: ['http', 'https'],
  require_protocol: true,
  require_valid_protocol: true,
  require_host: true,
  require_tld: true,
  require_port: false,
  allow_protocol_relative_urls: false,
  allow_trailing_dot: false,
  allow_underscores: false,
  disallow_auth: false,
};

const SCHEME_RE = /^https?:\/\//i;

// Captures the hostname: skips optional userinfo, stops before port, path, query or fragment.
const HOST_RE = /^https?:\/\/(?:[^@\/?#]*@)?([^\/?#:]*)(?::\d*)?(?=[\/?#]|$)/i;

function isFqdnHost(host: string): boolean {
  if (host.length === 0 || host.length > 253) {
    return false;
  }

  const labels = host.split('.');
  // At least two labels is required, which rejects "localhost" and bare names.
  if (labels.length < 2) {
    return false;
  }

  for (const label of labels) {
    if (!/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i.test(label)) {
      return false;
    }
  }

  const tld = labels[labels.length - 1];
  // TLD must be alphabetic (rejects IPv4 addresses) or an IDN punycode label.
  return /^[a-z]{2,}$/i.test(tld) || /^xn--[a-z0-9-]+$/i.test(tld);
}

export function solve(urls: string[]): string[] {
  return urls.filter((url) => {
    if (typeof url !== 'string') {
      return false;
    }
    if (/\s/.test(url)) {
      return false;
    }
    if (!SCHEME_RE.test(url)) {
      return false;
    }
    if (!lib.isURL(url, URL_OPTIONS)) {
      return false;
    }

    const match = HOST_RE.exec(url);
    if (!match) {
      return false;
    }

    return isFqdnHost(match[1].toLowerCase());
  });
}

export function solve(name: string, namespace: string): string {
  return lib.v5(name, namespace);
}

export function solve(text: string): string {
    // Manually encode the string as UTF-8 (no TextEncoder, which is not ECMAScript).
    // Iterating a string with for...of yields full code points; lone surrogates
    // are replaced with U+FFFD, matching standard UTF-8 encoders.
    const out: number[] = [];
    for (const ch of text) {
        let cp = ch.codePointAt(0) as number;
        if (cp >= 0xd800 && cp <= 0xdfff) {
            cp = 0xfffd;
        }
        if (cp < 0x80) {
            out.push(cp);
        } else if (cp < 0x800) {
            out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            out.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            out.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    // Delegate the MD5 computation to the library function.
    const digest = lib.md5(new Uint8Array(out));

    // Convert the 16 digest bytes to 32 lowercase hex characters.
    let hex = "";
    for (let i = 0; i < digest.length; i++) {
        hex += (digest[i] & 0xff).toString(16).padStart(2, "0");
    }
    return hex;
}

export function solve(word: string, dictionary: string[]): string {
    return lib.closest(word, dictionary);
}

export function solve(epochMs: number): string {
  if (!Number.isFinite(epochMs)) {
    throw new RangeError("epochMs must be a finite number");
  }

  // Floor to whole seconds so fractional milliseconds are dropped
  // and negative instants round toward the earlier second.
  const totalSeconds = Math.floor(epochMs / 1000);

  // Split into whole days (floored) and seconds within the day (0..86399).
  const days = Math.floor(totalSeconds / 86400);
  const secondOfDay = totalSeconds - days * 86400;

  // Convert days since 1970-01-01 to a proleptic Gregorian civil date
  // (algorithm based on Howard Hinnant's civil_from_days).
  const z = days + 719468;
  const era = Math.floor(z / 146097);
  const doe = z - era * 146097;
  const yoe = Math.floor(
    (doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365
  );
  let year = yoe + era * 400;
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const day = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const month = mp < 10 ? mp + 3 : mp - 9;
  if (month <= 2) {
    year += 1;
  }

  const hour = Math.floor(secondOfDay / 3600);
  const minute = Math.floor((secondOfDay % 3600) / 60);
  const second = secondOfDay % 60;

  const pad = (n: number, width: number): string =>
    String(Math.abs(n)).padStart(width, "0");

  // Years 0000–9999 use plain 4-digit form; others use the ISO expanded form ±YYYYYY.
  let yearStr: string;
  if (year >= 0 && year <= 9999) {
    yearStr = pad(year, 4);
  } else {
    yearStr = (year < 0 ? "-" : "+") + pad(year, 6);
  }

  return (
    `${yearStr}-${pad(month, 2)}-${pad(day, 2)}` +
    `T${pad(hour, 2)}:${pad(minute, 2)}:${pad(second, 2)}Z`
  );
}

const DAY_MS = 86400000;

// Groups:
// 1 year
// 2 month, 3 day                       (calendar date)
// 4 week, 5 weekday                    (week date)
// 6 ordinal day                        (ordinal date)
// 7 hour, 8 minute, 9 second, 10 fraction, 11 offset (time part, optional)
const PATTERN =
  /^(\d{4})(?:-(\d{2})-(\d{2})|-W(\d{2})-(\d)|-(\d{3}))(?:T(\d{2}):(\d{2})(?::(\d{2})(?:[.,](\d+))?)?(Z|[+-]\d{2}:\d{2})?)?$/;

const MONTH_DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function invalid(input: string, reason: string): never {
  throw new RangeError(`Invalid ISO 8601 date "${input}": ${reason}`);
}

function isLeap(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysInMonth(year: number, month1: number): number {
  return month1 === 2 && isLeap(year) ? 29 : MONTH_DAYS[month1 - 1];
}

/** UTC epoch ms of midnight on the given proleptic Gregorian date (valid for all years). */
function dayStart(year: number, monthIndex: number, day: number): number {
  const d = new Date(0);
  d.setUTCFullYear(year, monthIndex, day);
  return d.getTime();
}

/** UTC epoch ms of Monday of ISO week 1 for the given year. */
function isoWeek1Monday(year: number): number {
  const jan4 = dayStart(year, 0, 4);
  const dow = (new Date(jan4).getUTCDay() + 6) % 7; // Monday = 0 ... Sunday = 6
  return jan4 - dow * DAY_MS;
}

function isoWeeksInYear(year: number): number {
  return Math.round((isoWeek1Monday(year + 1) - isoWeek1Monday(year)) / (7 * DAY_MS));
}

function parseOne(input: string): number {
  const m = PATTERN.exec(input);
  if (!m) invalid(input, "unrecognized format");

  const year = Number(m[1]);
  let dayMs: number;

  if (m[2] !== undefined) {
    // Calendar date
    const month = Number(m[2]);
    const day = Number(m[3]);
    if (month < 1 || month > 12) invalid(input, "month out of range");
    if (day < 1 || day > daysInMonth(year, month)) invalid(input, "day out of range");
    dayMs = dayStart(year, month - 1, day);
  } else if (m[4] !== undefined) {
    // Week date
    const week = Number(m[4]);
    const weekday = Number(m[5]);
    if (week < 1 || week > isoWeeksInYear(year)) invalid(input, "week out of range");
    if (weekday < 1 || weekday > 7) invalid(input, "weekday out of range");
    dayMs = isoWeek1Monday(year) + ((week - 1) * 7 + (weekday - 1)) * DAY_MS;
  } else {
    // Ordinal date
    const ordinal = Number(m[6]);
    const daysInYear = isLeap(year) ? 366 : 365;
    if (ordinal < 1 || ordinal > daysInYear) invalid(input, "ordinal day out of range");
    dayMs = dayStart(year, 0, 1) + (ordinal - 1) * DAY_MS;
  }

  let timeMs = 0;
  let offsetMin = 0;

  if (m[7] !== undefined) {
    const hour = Number(m[7]);
    const minute = Number(m[8]);
    const second = m[9] !== undefined ? Number(m[9]) : 0;
    const fraction = m[10] || "";

    if (minute > 59) invalid(input, "minute out of range");
    // 60 is accepted as a leap second; the arithmetic below folds it into the next minute.
    if (second > 60) invalid(input, "second out of range");

    // 24:00:00 denotes the end of the day (start of the next day).
    const endOfDay = hour === 24 && minute === 0 && second === 0 && /^0*$/.test(fraction);
    if (hour > 23 && !endOfDay) invalid(input, "hour out of range");

    const ms = Number((fraction + "00").slice(0, 3));
    timeMs = ((hour * 60 + minute) * 60 + second) * 1000 + ms;

    const tz = m[11];
    if (tz !== undefined && tz !== "Z") {
      const sign = tz[0] === "-" ? -1 : 1;
      const oh = Number(tz.slice(1, 3));
      const om = Number(tz.slice(4, 6));
      if (oh > 23) invalid(input, "offset hour out of range");
      if (om > 59) invalid(input, "offset minute out of range");
      offsetMin = sign * (oh * 60 + om);
    }
  }

  // Without an explicit offset (or with no time), the value is UTC.
  return dayMs + timeMs - offsetMin * 60000;
}

export function solve(stamps: string[]): number[] {
  return stamps.map((s) => parseOne(s)).sort((a, b) => a - b);
}

export function solve(text: string): number[] {
  if (text.length % 4 !== 0) {
    throw new Error("Invalid base64 string: length must be a multiple of 4");
  }
  return Array.from(lib.toByteArray(text));
}

export function solve(nodes: string[], edges: [string, string][]): string[] {
  return lib.toposort(nodes, edges);
}

export function solve(range: string): string | null {
  let result: { version: string } | null;
  try {
    result = lib.minVersion(range);
  } catch {
    // An invalid range makes the Range constructor throw.
    return null;
  }
  return result ? result.version : null;
}

export function solve(versions: string[]): string[] {
  return [...versions].sort((a, b) => {
    const c = lib.compare(a, b);
    if (c !== 0) return c;
    // Equal precedence: order by build metadata, i.e. full string, lexically.
    return a < b ? -1 : a > b ? 1 : 0;
  });
}

export function solve(a: string, b: string): boolean {
  return lib.intersects(a, b);
}

export function solve(version: string, range: string): boolean {
  return lib.gtr(version, range);
}

export function solve(sub: string, sup: string): boolean {
  return lib.subset(sub, sup)
}

export function solve(text: string): string {
    // Manually encode the string as UTF-8 (no TextEncoder, since it is not ECMAScript).
    const bytes: number[] = [];
    for (let i = 0; i < text.length; i++) {
        let cp = text.charCodeAt(i);
        if (cp >= 0xd800 && cp <= 0xdbff && i + 1 < text.length) {
            const next = text.charCodeAt(i + 1);
            if (next >= 0xdc00 && next <= 0xdfff) {
                cp = 0x10000 + ((cp - 0xd800) << 10) + (next - 0xdc00);
                i++;
            } else {
                cp = 0xfffd; // lone high surrogate
            }
        } else if (cp >= 0xd800 && cp <= 0xdfff) {
            cp = 0xfffd; // lone surrogate
        }

        if (cp < 0x80) {
            bytes.push(cp);
        } else if (cp < 0x800) {
            bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            bytes.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f),
            );
        } else {
            bytes.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f),
            );
        }
    }

    const digest = lib.sha1(Uint8Array.from(bytes));

    let hex = "";
    for (let i = 0; i < digest.length; i++) {
        hex += digest[i].toString(16).padStart(2, "0");
    }
    return hex;
}

type BumpKind = 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease';
type Identifier = string | number;

interface ParsedSemVer {
  major: number;
  minor: number;
  patch: number;
  prerelease: Identifier[];
}

// Advances a prerelease array. Starting from an empty array this yields `<id>.0` or `0`.
function nextPrerelease(pre: Identifier[], id?: string): Identifier[] {
  if (!id || pre[0] === id) {
    const next = pre.slice();
    // Increment the last numeric part, or append 0 if there is none.
    for (let i = next.length - 1; i >= 0; i--) {
      const part = next[i];
      if (typeof part === 'number') {
        next[i] = part + 1;
        return next;
      }
    }
    next.push(0);
    return next;
  }
  // Different (or new) identifier: switch to `<id>.0`.
  return [id, 0];
}

export function solve(version: string, kind: BumpKind, id?: string): string | null {
  const parsed = lib.parse(version) as ParsedSemVer | null;
  if (!parsed) return null;

  // An identifier that is not a valid prerelease is treated as invalid input.
  if (id && lib.parse(`0.0.0-${id}`) === null) return null;

  const { major, minor, patch, prerelease } = parsed;
  const hasPre = prerelease.length > 0;

  let M = major;
  let m = minor;
  let p = patch;
  let pre: Identifier[] = [];

  switch (kind) {
    case 'major':
      // Releasing a prerelease only counts as a bump when lower parts are already zero.
      if (minor !== 0 || patch !== 0 || !hasPre) M++;
      m = 0;
      p = 0;
      break;

    case 'minor':
      if (patch !== 0 || !hasPre) m++;
      p = 0;
      break;

    case 'patch':
      if (!hasPre) p++;
      break;

    case 'premajor':
      M++;
      m = 0;
      p = 0;
      pre = nextPrerelease([], id);
      break;

    case 'preminor':
      m++;
      p = 0;
      pre = nextPrerelease([], id);
      break;

    case 'prepatch':
      p++;
      pre = nextPrerelease([], id);
      break;

    case 'prerelease':
      // A release bumps the patch first; a prerelease keeps its core version.
      if (!hasPre) p++;
      pre = nextPrerelease(prerelease, id);
      break;

    default:
      return null;
  }

  const core = `${M}.${m}.${p}`;
  return pre.length > 0 ? `${core}-${pre.join('.')}` : core;
}

type Parsed = { major: number; minor: number; patch: number; pre: boolean };

function parseVersion(v: string): Parsed {
  const m = /^\s*v?(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+[0-9A-Za-z.-]+)?\s*$/.exec(v);
  if (!m) {
    throw new TypeError(`Invalid semver version: ${v}`);
  }
  return {
    major: Number(m[1]),
    minor: Number(m[2]),
    patch: Number(m[3]),
    pre: m[4] !== undefined,
  };
}

function cmp(x: number, y: number): number {
  return x < y ? -1 : x > y ? 1 : 0;
}

function compareCore(x: Parsed, y: Parsed): number {
  return cmp(x.major, y.major) || cmp(x.minor, y.minor) || cmp(x.patch, y.patch);
}

export function solve(a: string, b: string): string | null {
  const result = lib.diff(a, b);
  if (result === null) {
    return null;
  }

  const va = parseVersion(a);
  const vb = parseVersion(b);
  const core = compareCore(va, vb);

  // Lower version: smaller core, or (equal cores) the prerelease one.
  const low = core < 0 || (core === 0 && va.pre) ? va : vb;
  const high = low === va ? vb : va;

  // Prerelease -> release with differing cores: the change is the highest
  // differing core part. lib.diff's shortcut wrongly returns 'major' whenever
  // the lower minor and patch are 0, so compute it directly here.
  if (low.pre && !high.pre && core !== 0) {
    if (low.major !== high.major) return 'major';
    if (low.minor !== high.minor) return 'minor';
    return 'patch';
  }

  // All other cases (including equal cores) are handled correctly by lib.diff.
  return result;
}

const MD5_SHIFTS: number[] = [
  7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
  5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20,
  4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
  6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21,
];

const MD5_K: number[] = Array.from({ length: 64 }, (_, i) =>
  Math.floor(Math.abs(Math.sin(i + 1)) * 4294967296) >>> 0
);

function md5(data: Uint8Array): Uint8Array {
  const len = data.length;
  const total = Math.ceil((len + 9) / 64) * 64;
  const padded = new Uint8Array(total);
  padded.set(data);
  padded[len] = 0x80;

  const view = new DataView(padded.buffer);
  view.setUint32(total - 8, (len * 8) >>> 0, true);
  view.setUint32(total - 4, Math.floor(len / 0x20000000) >>> 0, true);

  let a0 = 0x67452301;
  let b0 = 0xefcdab89;
  let c0 = 0x98badcfe;
  let d0 = 0x10325476;

  const M: number[] = new Array(16);

  for (let off = 0; off < total; off += 64) {
    for (let j = 0; j < 16; j++) {
      M[j] = view.getUint32(off + j * 4, true);
    }

    let A = a0;
    let B = b0;
    let C = c0;
    let D = d0;

    for (let i = 0; i < 64; i++) {
      let F: number;
      let g: number;
      if (i < 16) {
        F = (B & C) | (~B & D);
        g = i;
      } else if (i < 32) {
        F = (D & B) | (~D & C);
        g = (5 * i + 1) % 16;
      } else if (i < 48) {
        F = B ^ C ^ D;
        g = (3 * i + 5) % 16;
      } else {
        F = C ^ (B | ~D);
        g = (7 * i) % 16;
      }

      F = (F + A + MD5_K[i] + M[g]) >>> 0;
      A = D;
      D = C;
      C = B;
      const s = MD5_SHIFTS[i];
      B = (B + ((F << s) | (F >>> (32 - s)))) >>> 0;
    }

    a0 = (a0 + A) >>> 0;
    b0 = (b0 + B) >>> 0;
    c0 = (c0 + C) >>> 0;
    d0 = (d0 + D) >>> 0;
  }

  const out = new Uint8Array(16);
  const outView = new DataView(out.buffer);
  outView.setUint32(0, a0, true);
  outView.setUint32(4, b0, true);
  outView.setUint32(8, c0, true);
  outView.setUint32(12, d0, true);
  return out;
}

function utf8Encode(s: string): Uint8Array {
  const out: number[] = [];
  for (const ch of s) {
    let c = ch.codePointAt(0) as number;
    if (c >= 0xd800 && c <= 0xdfff) {
      c = 0xfffd; // lone surrogate -> replacement character
    }
    if (c < 0x80) {
      out.push(c);
    } else if (c < 0x800) {
      out.push(0xc0 | (c >> 6), 0x80 | (c & 0x3f));
    } else if (c < 0x10000) {
      out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
    } else {
      out.push(
        0xf0 | (c >> 18),
        0x80 | ((c >> 12) & 0x3f),
        0x80 | ((c >> 6) & 0x3f),
        0x80 | (c & 0x3f)
      );
    }
  }
  return Uint8Array.from(out);
}

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function solve(name: string, namespace: string): string {
  if (typeof name !== 'string') {
    throw new TypeError('name must be a string');
  }
  if (typeof namespace !== 'string' || !UUID_RE.test(namespace)) {
    throw new TypeError('namespace must be a valid UUID string');
  }

  const hex = namespace.replace(/-/g, '');
  const nsBytes = new Uint8Array(16);
  for (let i = 0; i < 16; i++) {
    nsBytes[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  }

  const valueBytes = utf8Encode(name);

  return lib.v35(3, md5, valueBytes, nsBytes) as string;
}

export function solve(text: string): string | null {
  // First run of 1 to 3 dot-separated digit groups, each 1 to 16 digits,
  // not adjacent to another digit on either side.
  const match = /(?<!\d)\d{1,16}(?:\.\d{1,16}){0,2}(?!\d)/.exec(text);
  if (match === null) {
    return null;
  }

  const parts = match[0].split('.');

  // Any number in the first run with a leading zero (other than a lone "0") invalidates the result.
  for (const part of parts) {
    if (part.length > 1 && part.startsWith('0')) {
      return null;
    }
  }

  const major = parts[0];
  const minor = parts.length > 1 ? parts[1] : '0';
  const patch = parts.length > 2 ? parts[2] : '0';
  const normalized = `${major}.${minor}.${patch}`;

  // Only trust the library's SemVer formatting when every number is a safe integer
  // (at most 15 digits). Otherwise keep the exact digit string.
  const allSafe = [major, minor, patch].every((p) => p.length <= 15);
  if (!allSafe) {
    return normalized;
  }

  const parsed = lib.coerce(normalized);
  return parsed === null ? normalized : parsed.version;
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  if (version === undefined) {
    return lib.isISBN(isbn);
  }
  if (version === 10 || version === 13) {
    return lib.isISBN(isbn, { version: version });
  }
  return false;
}

export function solve(isin: string): boolean {
  if (typeof isin !== 'string') {
    return false;
  }
  return lib.isISIN(isin);
}

export function solve(mac: string): boolean {
  // Delegate format validation (octet/group counts, hex digits, allowed
  // separators) to the library.
  if (!lib.isMACAddress(mac)) {
    return false;
  }

  // The library accepts each separator position independently, so it would
  // also accept mixed ':' and '-' separators. Reject that case here.
  const hasColon = mac.includes(':');
  const hasHyphen = mac.includes('-');
  if (hasColon && hasHyphen) {
    return false;
  }

  return true;
}

export function solve(iban: string): boolean {
  if (typeof iban !== "string") {
    return false;
  }
  const normalized = iban.replace(/[ -]/g, "").toUpperCase();
  return lib.isIBAN(normalized);
}

export function solve(issn: string): boolean {
  if (typeof issn !== 'string') {
    return false;
  }
  return lib.isISSN(issn);
}

export function solve(card: string): boolean {
  if (typeof card !== 'string') return false;

  // Remove spaces and hyphens only.
  const s = card.replace(/[ -]+/g, '');
  if (!/^\d+$/.test(s)) return false;

  // lib.isCreditCard is not used: its issuer patterns don't cover the ranges
  // required here (e.g. Discover 644-649 and 622126-622925, JCB 16-19 digits,
  // Diners 14-19 digits), so it would reject some cards this spec accepts.

  // True if the first `digits` digits of s fall within [lo, hi].
  const prefixMatches = (lo: number, hi: number, digits: number): boolean => {
    if (s.length < digits) return false;
    const p = Number(s.slice(0, digits));
    return p >= lo && p <= hi;
  };

  const range = (from: number, to: number): number[] => {
    const out: number[] = [];
    for (let i = from; i <= to; i++) out.push(i);
    return out;
  };

  // [lo, hi, prefixDigits] ranges, plus allowed lengths, per issuer.
  const issuers: Array<{ ranges: Array<[number, number, number]>; lengths: number[] }> = [
    // Visa: 4…, 13/16/19 digits
    { ranges: [[4, 4, 1]], lengths: [13, 16, 19] },
    // Mastercard: 51–55 or 2221–2720, 16 digits
    { ranges: [[51, 55, 2], [2221, 2720, 4]], lengths: [16] },
    // American Express: 34 or 37, 15 digits
    { ranges: [[34, 34, 2], [37, 37, 2]], lengths: [15] },
    // Discover: 6011, 622126–622925, 644–649, 65; 16 or 19 digits
    { ranges: [[6011, 6011, 4], [622126, 622925, 6], [644, 649, 3], [65, 65, 2]], lengths: [16, 19] },
    // Diners Club: 300–305, 36, 38; 14–19 digits
    { ranges: [[300, 305, 3], [36, 36, 2], [38, 38, 2]], lengths: range(14, 19) },
    // JCB: 3528–3589; 16–19 digits
    { ranges: [[3528, 3589, 4]], lengths: range(16, 19) },
    // UnionPay: 62; 16–19 digits
    { ranges: [[62, 62, 2]], lengths: range(16, 19) },
  ];

  const issuerOk = issuers.some(
    (iss) =>
      iss.lengths.includes(s.length) &&
      iss.ranges.some(([lo, hi, d]) => prefixMatches(lo, hi, d))
  );
  if (!issuerOk) return false;

  // Luhn check.
  let sum = 0;
  let double = false;
  for (let i = s.length - 1; i >= 0; i--) {
    let d = s.charCodeAt(i) - 48;
    if (double) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
    double = !double;
  }
  return sum % 10 === 0;
}

declare const lib: { isEAN(str: string): boolean };

export function solve(code: string): boolean {
  if (typeof code !== "string" || !/^\d+$/.test(code)) return false;

  // lib.isEAN handles EAN-8 and EAN-13 (its regex rejects 14-digit codes).
  if (code.length === 8 || code.length === 13) {
    return lib.isEAN(code);
  }

  // GTIN-14: weights 3,1,3,... from the left over the 13 data digits.
  if (code.length === 14) {
    let sum = 0;
    for (let i = 0; i < 13; i++) {
      sum += Number(code[i]) * (i % 2 === 0 ? 3 : 1);
    }
    const check = (10 - (sum % 10)) % 10;
    return check === Number(code[13]);
  }

  return false;
}

export function solve(text: string): boolean {
  let body = text;

  // Strip one pair of wrapping parentheses, if present.
  if (body.length >= 2 && body[0] === '(' && body[body.length - 1] === ')') {
    body = body.slice(1, -1);
  }

  // Any remaining parenthesis means unbalanced or doubled wrapping.
  if (body.includes('(') || body.includes(')')) return false;

  // Exactly one comma separates latitude and longitude.
  const parts = body.split(',');
  if (parts.length !== 2) return false;

  const latPart = parts[0];
  // Optional spaces are allowed only directly after the comma.
  const longPart = parts[1].replace(/^ +/, '');

  // No other whitespace is permitted (rejects space-only separators, etc.).
  if (/\s/.test(latPart) || /\s/.test(longPart)) return false;
  if (latPart === '' || longPart === '') return false;

  // Delegate the numeric/range validation to the library, using the
  // canonical form without parentheses or extra spaces.
  return lib.isLatLong(`${latPart},${longPart}`);
}

export function solve(a: string, b: string): number {
    return lib.distance(a, b);
}

const ZONE_ID_RE = /^[A-Za-z0-9]+$/;

// Link-local unicast is fe80::/10, i.e. the first 16-bit group is in [0xfe80, 0xfebf].
function isLinkLocalIPv6(addr: string): boolean {
  // A leading "::" means the first group is zero, so it is not link-local.
  if (addr.startsWith(':')) return false;
  const first = addr.split(':')[0];
  if (!/^[0-9a-fA-F]{1,4}$/.test(first)) return false;
  const value = parseInt(first, 16);
  return value >= 0xfe80 && value <= 0xfebf;
}

function isValidIPv6WithOptionalZone(text: string): boolean {
  const pct = text.indexOf('%');
  if (pct === -1) {
    return lib.isIP(text, { version: 6 });
  }
  const addr = text.slice(0, pct);
  const zone = text.slice(pct + 1);
  return (
    ZONE_ID_RE.test(zone) &&
    lib.isIP(addr, { version: 6 }) &&
    isLinkLocalIPv6(addr)
  );
}

export function solve(text: string, version?: 4 | 6): boolean {
  if (version === 4) {
    return lib.isIP(text, { version: 4 });
  }
  if (version === 6) {
    return isValidIPv6WithOptionalZone(text);
  }
  if (version === undefined) {
    return lib.isIP(text, { version: 4 }) || isValidIPv6WithOptionalZone(text);
  }
  return false;
}

export function solve(code: string): boolean {
  if (typeof code !== "string" || code.length !== 11) return false;
  // 3 owner letters, category U/J/Z (any case), 6 serial digits, 1 check digit
  if (!/^[A-Za-z]{3}[UJZ][0-9]{6}[0-9]$/i.test(code)) return false;
  return lib.isISO6346(code);
}

export function solve(range: string): string | null {
  return lib.validRange(range);
}

declare const lib: {
  get(obj: unknown, pointer: string): unknown;
};

const ARRAY_INDEX = /^(0|[1-9][0-9]*)$/;

function decodeToken(token: string): string {
  return token.replace(/~1/g, "/").replace(/~0/g, "~");
}

export function solve(doc: unknown, pointer: string): unknown {
  if (pointer === "") return doc;
  if (!pointer.startsWith("/")) {
    throw new Error("Invalid JSON Pointer: must be empty or start with '/'");
  }

  const tokens = pointer.slice(1).split("/").map(decodeToken);

  // Confirm each step exists as an own member or valid array index, so that
  // inherited properties (e.g. "constructor", "__proto__") or "-" are not
  // reported as found. lib.get would otherwise return them, and it throws
  // when the document is a primitive.
  let cur: unknown = doc;
  for (const token of tokens) {
    if (cur === null || typeof cur !== "object") return undefined;
    if (Array.isArray(cur)) {
      if (!ARRAY_INDEX.test(token)) return undefined;
      const index = Number(token);
      if (index >= cur.length) return undefined;
      cur = cur[index];
    } else {
      if (!Object.prototype.hasOwnProperty.call(cur, token)) return undefined;
      cur = (cur as Record<string, unknown>)[token];
    }
  }

  return lib.get(doc, pointer);
}

export function solve(version: string, range: string): boolean {
  return lib.ltr(version, range);
}

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

export function solve(uuid: string): string | null {
    if (typeof uuid !== 'string' || !UUID_RE.test(uuid)) {
        return null;
    }
    return (lib.v1ToV6(uuid) as string).toLowerCase();
}

export function solve(name: string): boolean {
  if (typeof name !== 'string') return false;

  // Whole name length limit (253 characters)
  if (name.length === 0 || name.length > 253) return false;

  // No trailing dot
  if (name.endsWith('.')) return false;

  // At least two labels
  const labels = name.split('.');
  if (labels.length < 2) return false;

  // Each label: 1-63 chars, letters (international allowed), digits, hyphens only
  const LABEL_CHARS = /^[\p{L}0-9-]+$/u;
  for (const label of labels) {
    if (label.length < 1 || label.length > 63) return false;
    if (!LABEL_CHARS.test(label)) return false;
  }

  // TLD: at least 2 letters (international allowed), or a punycode label starting with "xn--"
  const tld = labels[labels.length - 1];
  const TLD_PATTERN = /^(?:\p{L}{2,}|xn--[a-z0-9-]*)$/iu;
  if (!TLD_PATTERN.test(tld)) return false;

  // Delegate the heavy lifting (hyphen placement, underscores, numeric TLDs, etc.)
  return lib.isFQDN(name, {
    require_tld: true,
    allow_underscores: false,
    allow_trailing_dot: false,
    allow_numeric_tld: false,
    allow_wildcard: false,
    ignore_max_length: false,
  });
}

export function solve(versions: string[], range: string): string | null {
  // Skip non-string entries so the library never receives a non-version value.
  // Invalid version strings are already rejected by the library's range test.
  const candidates = Array.isArray(versions)
    ? versions.filter((v): v is string => typeof v === "string")
    : [];

  const result = lib.minSatisfying(candidates, range);
  return result ?? null;
}

export function solve(egn: string): boolean {
  if (typeof egn !== "string" || !/^\d{10}$/.test(egn)) {
    return false;
  }

  const d = egn.split("").map(Number);

  const yy = d[0] * 10 + d[1];
  let mm = d[2] * 10 + d[3];
  const dd = d[4] * 10 + d[5];

  // Month field encodes the century:
  // 01-12 -> 1900s, 21-32 -> 1800s, 41-52 -> 2000s, 61-72 -> 2100s
  let century: number;
  if (mm >= 1 && mm <= 12) {
    century = 1900;
  } else if (mm >= 21 && mm <= 32) {
    century = 1800;
    mm -= 20;
  } else if (mm >= 41 && mm <= 52) {
    century = 2000;
    mm -= 40;
  } else if (mm >= 61 && mm <= 72) {
    century = 2100;
    mm -= 60;
  } else {
    return false;
  }

  const year = century + yy;
  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  if (dd < 1 || dd > daysInMonth[mm - 1]) {
    return false;
  }

  // Check digit: weighted sum of first 9 digits, mod 11; 10 maps to 0
  const weights = [2, 4, 8, 5, 10, 9, 7, 3, 6];
  let sum = 0;
  for (let i = 0; i < 9; i++) {
    sum += d[i] * weights[i];
  }
  let check = sum % 11;
  if (check === 10) {
    check = 0;
  }

  return check === d[9];
}

export function solve(sub: string, sup: string): boolean {
  return lib.subset(sub, sup);
}

export function solve(installed: string[], range: string): string | null {
  // Non-string entries can never be valid versions, so drop them before delegating.
  const candidates = installed.filter((v): v is string => typeof v === "string");
  // The library skips invalid version strings and applies npm's prerelease rules.
  return lib.maxSatisfying(candidates, range);
}

export function solve(obj: object, updates: [string | (string | number)[], unknown][]): object {
  for (const [path, value] of updates) {
    lib.set(obj, path, value);
  }
  return obj;
}

export function solve<T>(value: T): T {
  return lib.cloneDeep(value);
}

export function solve(emails: string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];

  const stripPlusSuffix = (local: string): string => {
    const plus = local.indexOf("+");
    return plus === -1 ? local : local.slice(0, plus);
  };

  // Remove single dots only; runs of two or more dots are kept as they are.
  const removeSingleDots = (local: string): string =>
    local.replace(/\.+/g, (run) => (run.length === 1 ? "" : run));

  for (const raw of emails) {
    const email = raw.toLowerCase();
    const at = email.lastIndexOf("@");

    let canonical: string;
    if (at === -1) {
      canonical = email;
    } else {
      let local = email.slice(0, at);
      let domain = email.slice(at + 1);

      if (domain === "gmail.com" || domain === "googlemail.com") {
        local = removeSingleDots(stripPlusSuffix(local));
        domain = "gmail.com";
      } else if (
        domain === "outlook.com" ||
        domain === "hotmail.com" ||
        domain === "live.com"
      ) {
        local = stripPlusSuffix(local);
      }

      canonical = `${local}@${domain}`;
    }

    if (!seen.has(canonical)) {
      seen.add(canonical);
      result.push(canonical);
    }
  }

  return result;
}

export function solve(id: string): boolean {
  // Remove slashes and backslashes
  const s = id.replace(/[\/\\]/g, '');

  // Exactly 11 digits, first digit must not be 0
  if (!/^\d{11}$/.test(s)) return false;
  if (s[0] === '0') return false;

  // Repeated-digit rule on the first 10 digits (check digit excluded):
  // no digit may appear more than 3 times, and either exactly one digit
  // appears 2 or 3 times (all others at most once), or exactly two digits
  // appear twice each (all others at most once).
  const counts: number[] = new Array(10).fill(0);
  for (let i = 0; i < 10; i++) {
    counts[Number(s[i])]++;
  }
  const maxCount = Math.max(...counts);
  if (maxCount > 3) return false;

  const repeated = counts.filter((c) => c >= 2);
  let repeatOk = false;
  if (repeated.length === 1 && (repeated[0] === 2 || repeated[0] === 3)) {
    repeatOk = true;
  } else if (repeated.length === 2 && repeated[0] === 2 && repeated[1] === 2) {
    repeatOk = true;
  }
  if (!repeatOk) return false;

  // Check digit via the Verhoeff algorithm
  return lib.verhoeffCheck(s);
}

export function solve(stamps: string[]): number[] {
  // True if the time portion of the string carries its own Z or ±hh[:mm] offset.
  const hasOffset = (s: string): boolean => {
    const delim = s.search(/[Tt ]/);
    if (delim < 0) return false; // date-only string, no offset possible
    return /(?:[Zz]|[+-]\d{2}(?::?\d{2})?)$/.test(s.slice(delim + 1));
  };

  const results = stamps.map((s) => {
    if (typeof s !== "string") {
      throw new RangeError(`Invalid date: ${String(s)}`);
    }
    // lib.parseISO interprets offset-less input through local wall-clock fields,
    // which breaks under DST and non-UTC host zones. Appending "Z" forces the
    // explicit-offset path, which is exact and timezone-independent.
    const normalized = hasOffset(s) ? s : s + "Z";
    const ms = +lib.parseISO(normalized);
    if (Number.isNaN(ms)) {
      throw new RangeError(`Invalid date: ${s}`);
    }
    return ms;
  });

  return results.sort((a, b) => a - b);
}

export function solve(id: string): boolean {
  // Optional slash after the 6-digit date; serial is 3 digits (9-digit form)
  // or 4 digits including the check digit (10-digit form).
  const m = /^(\d{2})(\d{2})(\d{2})\/?(\d{3,4})$/.exec(id);
  if (!m) return false;

  const yy = Number(m[1]);
  const mm = Number(m[2]);
  const dd = Number(m[3]);
  const tail = m[4];
  const is10 = tail.length === 4;

  let year: number;
  if (is10) {
    // Two-digit year below 54 is 20YY, otherwise 19YY.
    year = yy < 54 ? 2000 + yy : 1900 + yy;
  } else {
    // 9-digit form: issued before 1954, so year must be below 54 (19YY),
    // and the serial must not be 000.
    if (yy >= 54) return false;
    if (tail === "000") return false;
    year = 1900 + yy;
  }

  // Month: 01-12 men, 51-62 women, +20 (men) and +70 (women) from 2004 on.
  let month: number;
  if (mm >= 1 && mm <= 12) {
    month = mm;
  } else if (mm >= 51 && mm <= 62) {
    month = mm - 50;
  } else if (mm >= 21 && mm <= 32) {
    if (year < 2004) return false;
    month = mm - 20;
  } else if (mm >= 71 && mm <= 82) {
    if (year < 2004) return false;
    month = mm - 70;
  } else {
    return false;
  }

  // Day validity, including leap years.
  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[month - 1]) return false;

  if (!is10) return true;

  // 10-digit form: first 9 digits mod 11 gives the check digit;
  // remainder 10 is represented by check digit 0.
  const first9 = Number(m[1] + m[2] + m[3] + tail.slice(0, 3));
  const r = first9 % 11;
  const expected = r === 10 ? 0 : r;
  return Number(tail[3]) === expected;
}

const LABEL_RE = /^[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$/;
const TLD_RE = /^(?:[A-Za-z]{2,63}|xn--[A-Za-z0-9-]{1,59})$/;
const PORT_RE = /^\d{1,5}$/;

const URL_OPTIONS = {
  protocols: ['http', 'https'],
  require_protocol: true,
  require_valid_protocol: true,
  require_tld: true,
  require_host: true,
  require_port: false,
  allow_underscores: false,
  allow_trailing_dot: false,
  allow_protocol_relative_urls: false,
  allow_fragments: true,
  allow_query_components: true,
  validate_length: true,
  max_allowed_length: 2083,
};

function hasFQDNHttpHost(url: string): boolean {
  // Scheme must be exactly http:// or https:// (case-insensitive).
  const m = /^https?:\/\/([^/?#]*)/i.exec(url);
  if (!m) return false;

  let authority = m[1];
  if (authority.length === 0) return false;

  // Strip userinfo (user:pass@).
  const at = authority.lastIndexOf('@');
  if (at !== -1) authority = authority.slice(at + 1);

  // Split off optional port.
  const colon = authority.indexOf(':');
  let host = authority;
  if (colon !== -1) {
    host = authority.slice(0, colon);
    const port = authority.slice(colon + 1);
    if (!PORT_RE.test(port)) return false;
  }

  // Host must be a dotted name with at least two labels.
  const labels = host.split('.');
  if (labels.length < 2) return false;
  if (!labels.every((label) => LABEL_RE.test(label))) return false;

  // Top-level domain is required and must not be numeric (rejects IPv4 literals).
  return TLD_RE.test(labels[labels.length - 1]);
}

export function solve(urls: string[]): string[] {
  return urls.filter((url) => {
    if (typeof url !== 'string') return false;
    if (/\s/.test(url)) return false;
    if (!lib.isURL(url, URL_OPTIONS)) return false;
    return hasFQDNHttpHost(url);
  });
}

export function solve(word: string, dictionary: string[]): string {
  // lib.closest returns undefined for an empty array, so guard that case
  if (dictionary.length === 0) {
    return "";
  }
  // lib.closest keeps the first entry on ties (strict "<" comparison)
  return lib.closest(word, dictionary);
}

export function solve(nodes: string[], edges: [string, string][]): string[] {
  // lib.toposort throws on cycles and on edges that reference unknown nodes.
  return lib.toposort(nodes, edges);
}

export function solve(text: string): number[] {
  if (text.length % 4 !== 0) {
    throw new Error("Invalid base64 string: length must be a multiple of 4");
  }
  return Array.from(lib.toByteArray(text));
}

export function solve(epochMs: number): string {
  if (!Number.isFinite(epochMs)) {
    throw new RangeError("Invalid time value");
  }

  // Floor to whole seconds (correct for negative and fractional inputs).
  const wholeSeconds = Math.floor(Math.floor(epochMs) / 1000);
  const d = new Date(wholeSeconds * 1000);

  if (Number.isNaN(d.getTime())) {
    throw new RangeError("Time value out of range");
  }

  const pad = (n: number, width: number): string => String(n).padStart(width, "0");

  const year = d.getUTCFullYear();
  // ISO 8601: 4-digit years for 0000-9999, expanded signed 6-digit years otherwise.
  const yearStr =
    year >= 0 && year <= 9999
      ? pad(year, 4)
      : (year < 0 ? "-" : "+") + pad(Math.abs(year), 6);

  const month = pad(d.getUTCMonth() + 1, 2);
  const day = pad(d.getUTCDate(), 2);
  const hours = pad(d.getUTCHours(), 2);
  const minutes = pad(d.getUTCMinutes(), 2);
  const seconds = pad(d.getUTCSeconds(), 2);

  return `${yearStr}-${month}-${day}T${hours}:${minutes}:${seconds}Z`;
}

export function solve(range: string): string | null {
  try {
    const minver = lib.minVersion(range);
    return minver ? minver.format() : null;
  } catch {
    // Invalid range expressions make the underlying Range constructor throw.
    return null;
  }
}

export function solve(text: string): string {
    // Manually encode the string as UTF-8 (no TextEncoder, since it is not ECMAScript).
    const bytes: number[] = [];
    for (let i = 0; i < text.length; i++) {
        let cp = text.charCodeAt(i);

        if (cp >= 0xD800 && cp <= 0xDBFF) {
            // High surrogate: combine with a following low surrogate if present.
            const next = i + 1 < text.length ? text.charCodeAt(i + 1) : 0;
