type Parts = { major: number; minor: number; patch: number; pre: boolean };

function parseParts(v: string): Parts {
  const noBuild = v.split('+')[0];
  const dash = noBuild.indexOf('-');
  const core = dash === -1 ? noBuild : noBuild.slice(0, dash);
  const [major, minor, patch] = core.split('.').map(Number);
  return { major, minor, patch, pre: dash !== -1 };
}

function highestDiff(l: Parts, h: Parts): 'major' | 'minor' | 'patch' | null {
  if (l.major !== h.major) return 'major';
  if (l.minor !== h.minor) return 'minor';
  if (l.patch !== h.patch) return 'patch';
  return null;
}

export function solve(a: string, b: string): string | null {
  const cmp: number = lib.compare(a, b);
  if (cmp === 0) return null;

  const [lo, hi] = cmp < 0 ? [a, b] : [b, a];
  const L = parseParts(lo);
  const H = parseParts(hi);
  const diff = highestDiff(L, H);

  // Lower is a prerelease, higher is a release
  if (L.pre && !H.pre) {
    // lower minor and patch are 0: major (covers major-only change and equal cores)
    if (L.minor === 0 && L.patch === 0) return 'major';
    // cores equal: minor if lower minor set and patch zero, otherwise patch
    if (diff === null) {
      return L.minor !== 0 && L.patch === 0 ? 'minor' : 'patch';
    }
    // otherwise fall through to the highest differing core part
  }

  // Equal cores with a prerelease higher version
  if (diff === null) return 'prerelease';

  // Highest differing core part, prefixed with 'pre' when the higher is a prerelease
  return (H.pre ? 'pre' : '') + diff;
}

