type Issuer = {
  minLen: number;
  maxLen: number;
  matches: (d: string) => boolean;
};

// True if the first n digits of d, read as an integer, fall within [lo, hi].
function within(d: string, n: number, lo: number, hi: number): boolean {
  if (d.length < n) return false;
  const prefix = Number(d.slice(0, n));
  return prefix >= lo && prefix <= hi;
}

const ISSUERS: Issuer[] = [
  // Visa: 4…, 13/16/19 digits
  {
    minLen: 13,
    maxLen: 19,
    matches: (d) => d[0] === "4" && (d.length === 13 || d.length === 16 || d.length === 19),
  },
  // Mastercard: 51–55 or 2221–2720, 16 digits
  {
    minLen: 16,
    maxLen: 16,
    matches: (d) => within(d, 2, 51, 55) || within(d, 4, 2221, 2720),
  },
  // American Express: 34/37, 15 digits
  {
    minLen: 15,
    maxLen: 15,
    matches: (d) => within(d, 2, 34, 34) || within(d, 2, 37, 37),
  },
  // Discover: 6011, 622126–622925, 644–649, 65; 16 or 19 digits
  {
    minLen: 16,
    maxLen: 19,
    matches: (d) =>
      (d.length === 16 || d.length === 19) &&
      (within(d, 4, 6011, 6011) ||
        within(d, 6, 622126, 622925) ||
        within(d, 3, 644, 649) ||
        within(d, 2, 65, 65)),
  },
  // Diners Club: 300–305, 36, 38; 14–19 digits
  {
    minLen: 14,
    maxLen: 19,
    matches: (d) =>
      within(d, 3, 300, 305) || within(d, 2, 36, 36) || within(d, 2, 38, 38),
  },
  // JCB: 3528–3589; 16–19 digits
  {
    minLen: 16,
    maxLen: 19,
    matches: (d) => within(d, 4, 3528, 3589),
  },
  // UnionPay: 62; 16–19 digits
  {
    minLen: 16,
    maxLen: 19,
    matches: (d) => within(d, 2, 62, 62),
  },
];

function luhn(d: string): boolean {
  let sum = 0;
  let double = false;
  for (let i = d.length - 1; i >= 0; i--) {
    let n = d.charCodeAt(i) - 48;
    if (double) {
      n *= 2;
      if (n > 9) n -= 9;
    }
    sum += n;
    double = !double;
  }
  return sum % 10 === 0;
}

export function solve(card: string): boolean {
  const digits = card.replace(/[ -]/g, "");
  if (!/^\d+$/.test(digits)) return false;

  const issuerMatch = ISSUERS.some(
    (issuer) =>
      digits.length >= issuer.minLen &&
      digits.length <= issuer.maxLen &&
      issuer.matches(digits)
  );
  if (!issuerMatch) return false;

  return luhn(digits);
}

declare const lib: { isISIN(str: string): boolean };

export function solve(isin: string): boolean {
  return lib.isISIN(isin);
}

export function solve(text: string, version?: 4 | 6): boolean {
  if (typeof text !== 'string') return false;

  if (version === undefined || version === 4) {
    if (isStrictIPv4(text)) return true;
  }
  if (version === undefined || version === 6) {
    if (isStrictIPv6(text)) return true;
  }
  return false;
}

function isStrictIPv4(s: string): boolean {
  // Reject leading zeros explicitly; "0" alone is allowed.
  const m = /^(0|[1-9][0-9]{0,2})\.(0|[1-9][0-9]{0,2})\.(0|[1-9][0-9]{0,2})\.(0|[1-9][0-9]{0,2})$/.exec(s);
  if (!m) return false;
  for (let i = 1; i <= 4; i++) {
    if (Number(m[i]) > 255) return false;
  }
  return lib.isIP(s, { version: 4 });
}

function isStrictIPv6(s: string): boolean {
  let addr = s;
  const pct = s.indexOf('%');
  if (pct !== -1) {
    addr = s.slice(0, pct);
    const zone = s.slice(pct + 1);
    // Zone index: one or more alphanumerics.
    if (!/^[A-Za-z0-9]+$/.test(zone)) return false;
    // Zone index is only permitted on link-local addresses (fe80::/10).
    // The first group must be exactly four hex digits in the range fe80..febf.
    // An address starting with "::" has a zero first group and is not link-local.
    const first = addr.split(':')[0];
    if (!/^fe[89ab][0-9a-f]$/i.test(first)) return false;
  }
  return lib.isIP(addr, { version: 6 });
}

export function solve(mac: string): boolean {
  if (typeof mac !== 'string') {
    return false;
  }

  // The library handles the EUI-48/EUI-64 structure, hex digits,
  // group counts, and the dotted form.
  if (!lib.isMACAddress(mac)) {
    return false;
  }

  // The library permits mixing ':' and '-' as separators, so reject that here.
  // Dotted notation contains no ':' or '-', so it is unaffected.
  const hasColon = mac.indexOf(':') !== -1;
  const hasHyphen = mac.indexOf('-') !== -1;
  if (hasColon && hasHyphen) {
    return false;
  }

  return true;
}

export function solve(code: string): boolean {
  if (typeof code !== 'string' || !/^\d+$/.test(code)) {
    return false;
  }

  // EAN-8 and EAN-13: delegate to the library.
  if (code.length === 8 || code.length === 13) {
    return lib.isEAN(code);
  }

  // GTIN-14: the library's regex rejects 14 digits, so compute the check digit here.
  // Weights alternate 3, 1, ... starting from the rightmost data digit (index 12).
  if (code.length === 14) {
    let sum = 0;
    for (let i = 0; i < 13; i++) {
      const digit = code.charCodeAt(i) - 48;
      const weight = (12 - i) % 2 === 0 ? 3 : 1;
      sum += digit * weight;
    }
    const check = (10 - (sum % 10)) % 10;
    return check === code.charCodeAt(13) - 48;
  }

  return false;
}

export function solve(issn: string): boolean {
  // Strict format: NNNN-NNNC or NNNNNNNC, where C is a digit or X/x
  if (!/^\d{4}-?\d{3}[\dXx]$/.test(issn)) {
    return false;
  }

  // Normalize to the hyphen-free, upper-case form expected by the checksum
  const normalized = issn.replace('-', '').toUpperCase();

  return lib.isISSN(normalized);
}

export function solve(text: string): boolean {
  // The library silently ignores anything after a second comma, so reject
  // inputs that do not contain exactly one comma.
  if (text.split(',').length !== 2) return false;

  // The task allows any number of spaces after the comma, but the library's
  // long-regex tolerates only one. Collapse the run to a single space.
  const normalized = text.replace(/, +/, ', ');

  return lib.isLatLong(normalized, { checkDMS: false });
}

export function solve(a: string, b: string): number {
    return lib.distance(a, b);
}

const LABEL_CHARS = /^[\p{L}0-9-]+$/u;
const PUNYCODE_TLD = /^xn--/i;
const ALPHA_TLD = /^\p{L}{2,}$/u;

const codePointLength = (s: string): number => Array.from(s).length;

export function solve(name: string): boolean {
  if (typeof name !== 'string' || name.length === 0) return false;
  if (name.endsWith('.')) return false;
  if (codePointLength(name) > 253) return false;

  const labels = name.split('.');
  if (labels.length < 2) return false;

  if (!lib.isFQDN(name, {
    require_tld: true,
    allow_trailing_dot: false,
    allow_wildcard: false,
    allow_numeric_tld: false,
    allow_underscores: false,
    ignore_max_length: true,
  })) {
    return false;
  }

  for (const label of labels) {
    const len = codePointLength(label);
    if (len < 1 || len > 63) return false;
    if (!LABEL_CHARS.test(label)) return false;
    if (label.startsWith('-') || label.endsWith('-')) return false;
  }

  const tld = labels[labels.length - 1];
  if (codePointLength(tld) < 2) return false;
  if (!PUNYCODE_TLD.test(tld) && !ALPHA_TLD.test(tld)) return false;

  return true;
}

export function solve(doc: unknown, pointer: string): unknown {
  // The empty pointer refers to the whole document (any type).
  if (pointer === '') return doc;

  if (pointer[0] !== '/') {
    throw new Error('Invalid JSON Pointer: must be empty or start with "/".');
  }

  // Pre-check each step so that missing members and inherited properties
  // (e.g. "constructor", "__proto__") yield undefined instead of leaking
  // values from the prototype chain. lib.get also throws for non-object
  // roots and null, so those are handled here too.
  const tokens = pointer
    .slice(1)
    .split('/')
    .map((t) => t.replace(/~1/g, '/').replace(/~0/g, '~'));

  let cur: unknown = doc;
  for (const token of tokens) {
    if (typeof cur !== 'object' || cur === null) return undefined;

    if (Array.isArray(cur)) {
      // Array steps must be canonical indices within bounds.
      if (!/^(0|[1-9][0-9]*)$/.test(token)) return undefined;
      const idx = Number(token);
      if (idx >= cur.length) return undefined;
      cur = cur[idx];
    } else {
      if (!Object.prototype.hasOwnProperty.call(cur, token)) return undefined;
      cur = (cur as Record<string, unknown>)[token];
    }
  }

  // Every step exists and the root is an object, so delegate the
  // actual resolution to the library.
  return lib.get(doc as object, pointer);
}

export function solve(code: string): boolean {
  if (typeof code !== "string" || code.length !== 11) return false;
  if (!/^[A-Za-z]{3}[UJZ][0-9]{7}$/i.test(code)) return false;
  return lib.isISO6346(code);
}

export function solve(versions: string[], range: string): string | null {
  return lib.minSatisfying(versions, range);
}

export function solve(version: string, range: string): boolean {
  return lib.ltr(version, range);
}

export function solve(range: string): string | null {
  try {
    const parsed = new lib.Range(range);
    const normalized: string = parsed.range;
    // An empty formatted string means the range matches every version.
    return normalized === '' ? '*' : normalized;
  } catch {
    return null;
  }
}

export function solve(uuid: string): string | null {
    // Canonical 8-4-4-4-12 hexadecimal form, hyphens required, either case.
    const pattern = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
    if (typeof uuid !== 'string' || !pattern.test(uuid)) {
        return null;
    }

    // RFC 9562 variant: the first hex digit of the fourth group (index 19) must be 8, 9, a or b.
    const variant = uuid.charAt(19).toLowerCase();
    if (variant !== '8' && variant !== '9' && variant !== 'a' && variant !== 'b') {
        return null;
    }

    // Normalise to lowercase before handing off to the library.
    const lower = uuid.toLowerCase();
    return lib.v1ToV6(lower) as string;
}

export function solve(egn: string): boolean {
  if (!/^\d{10}$/.test(egn)) return false;

  const d = egn.split('').map(Number);

  // Year (last two digits)
  const yy = d[0] * 10 + d[1];

  // Month with century offset
  const mm = d[2] * 10 + d[3];
  let year: number;
  let month: number;

  if (mm >= 1 && mm <= 12) {
    year = 1900 + yy;
    month = mm;
  } else if (mm >= 21 && mm <= 32) {
    year = 1800 + yy;
    month = mm - 20;
  } else if (mm >= 41 && mm <= 52) {
    year = 2000 + yy;
    month = mm - 40;
  } else {
    return false;
  }

  // Day validity (Gregorian leap year rules)
  const dd = d[4] * 10 + d[5];
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[month - 1]) return false;

  // Check digit: weighted sum of first 9 digits, mod 11; 10 maps to 0
  const weights = [2, 4, 8, 5, 10, 9, 7, 3, 6];
  let sum = 0;
  for (let i = 0; i < 9; i++) {
    sum += d[i] * weights[i];
  }
  const r = sum % 11;
  const check = r === 10 ? 0 : r;

  return check === d[9];
}

export function solve(id: string): boolean {
  // Remove slashes and backslashes
  const s = id.replace(/[\/\\]/g, '');

  // Must be exactly 11 digits
  if (!/^\d{11}$/.test(s)) return false;

  // First digit must not be zero
  if (s[0] === '0') return false;

  // Among the first 10 digits: exactly one digit occurs 2 or 3 times,
  // all other digits occur at most once
  const counts: number[] = new Array(10).fill(0);
  for (let i = 0; i < 10; i++) {
    counts[parseInt(s[i], 10)]++;
  }

  let repeated = 0;
  for (const c of counts) {
    if (c === 2 || c === 3) {
      repeated++;
    } else if (c > 1) {
      return false;
    }
  }
  if (repeated !== 1) return false;

  // Check digit via Verhoeff algorithm
  return lib.verhoeffCheck(s);
}

export function solve(id: string): boolean {
  const m = /^(\d{2})(\d{2})(\d{2})\/?(\d{3})(\d?)$/.exec(id);
  if (!m) return false;

  const yy = Number(m[1]);
  const rawMonth = Number(m[2]);
  const dd = Number(m[3]);
  const serial = m[4];
  const check = m[5];
  const isTenDigit = check !== "";

  let year: number;
  if (isTenDigit) {
    year = yy < 54 ? 2000 + yy : 1900 + yy;
  } else {
    // 9-digit form: issued before 1954, so the year must be 1900-1953
    if (yy >= 54) return false;
    if (serial === "000") return false;
    year = 1900 + yy;
  }

  // Decode month: women +50, and from 2004 an additional +20 (men) or +70 (women)
  let month: number;
  if (year >= 2004 && rawMonth >= 71 && rawMonth <= 82) {
    month = rawMonth - 70;
  } else if (rawMonth >= 51 && rawMonth <= 62) {
    month = rawMonth - 50;
  } else if (year >= 2004 && rawMonth >= 21 && rawMonth <= 32) {
    month = rawMonth - 20;
  } else {
    month = rawMonth;
  }

  if (month < 1 || month > 12) return false;

  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[month - 1]) return false;

  if (!isTenDigit) return true;

  // 10-digit form: the first 9 digits modulo 11 give the check digit (remainder 10 -> 0)
  const base = Number(m[1] + m[2] + m[3] + serial);
  let r = base % 11;
  if (r === 10) r = 0;
  return r === Number(check);
}
